package wallet

import "time"

// Balances 表示账户当前的资金状态，单位均为最小货币单位的整数。
type Balances struct {
	// Available 为可用于新预留的余额（初始余额减去已预留和已扣减）。
	Available int64
	// Reserved 为已受理但尚未结算或取消的请求所预留的费用总额。
	Reserved int64
}

// AccountView 是账户的只读视图。
type AccountView struct {
	ID        string
	Balances  Balances
	CreatedAt time.Time
}

// SessionState 描述会话状态。
type SessionState int

const (
	// SessionActive 有效会话。
	SessionActive SessionState = iota
	// SessionRevoked 已被主动吊销。
	SessionRevoked
)

// SessionView 是会话的只读视图。
type SessionView struct {
	ID        string
	AccountID string
	DeviceID  string
	ExpiresAt time.Time
	State     SessionState
	CreatedAt time.Time
}

// PolicySpec 定义一条代付策略。
//
// 多个使用账户共享同一累计额度。时间窗为 [StartsAt, EndsAt)。
type PolicySpec struct {
	// ID 为策略唯一编号，留空时拒绝保存。
	ID string
	// PayerAccountID 为出资账户。
	PayerAccountID string
	// AllowedAccountIDs 为允许发起代付的使用账户列表，不能为空。
	AllowedAccountIDs []string
	// Operation 为允许的操作类型，不能为空。
	Operation string
	// Payee 为允许的收款方，不能为空。
	Payee string
	// StartsAt 为授权时间窗起点（含）。
	StartsAt time.Time
	// EndsAt 为授权时间窗终点（不含）。
	EndsAt time.Time
	// MaxPerRequest 为单次费用上限，必须为正。
	MaxPerRequest int64
	// MaxTotal 为所有使用账户共享的累计费用上限，必须为正。
	MaxTotal int64
	// ApprovalThreshold 为大额审批门槛：预估费用严格超过此值的申请进入
	// 待审批，由出资账户审批通过后才预留。零表示关闭审批，申请直接预留；
	// 不得为负，且不得超过单次费用上限。
	ApprovalThreshold int64
	// ApprovalWait 为待审批请求的最长等待时长（自提交时刻起算）。
	// 审批开启（ApprovalThreshold 为正）时必须为正；关闭时忽略。
	ApprovalWait time.Duration
	// MaxReserveDuration 为已预留请求的最长预留时长：自直接受理时刻，或
	// 待审批请求被批准成功的时刻起算（等待审批的时间不计入）。零表示关闭
	// 预留超时，已预留费用只在结算或取消时释放；不得为负。
	MaxReserveDuration time.Duration
}

// PolicyView 是策略的只读视图。
type PolicyView struct {
	PolicySpec
	// ReservedTotal 为当前处于预留中的费用总额（占用累计额度）。
	ReservedTotal int64
	// SpentTotal 为已结算扣除的累计费用。
	SpentTotal int64
	// Deactivated 表示策略是否已被出资账户主动停用；新保存的策略为 false。
	// 停用不可撤销，停用后策略不再受理新申请，编号也不能重新保存为新策略。
	Deactivated bool
	// DeactivatedAt 为首次停用时间；未停用时为零值。
	DeactivatedAt time.Time
	// DeactivatorAccountID 为执行停用的出资账户；未停用时为空。
	DeactivatorAccountID string
	// DeactivateReason 为去掉首尾空白后的停用理由；未停用时为空。
	DeactivateReason string
}

// RequestState 描述代付请求的生命周期状态。
type RequestState int

const (
	// RequestReserved 已受理并完成费用预留，等待结算或取消。
	RequestReserved RequestState = iota
	// RequestSettled 已按实际费用结算。
	RequestSettled
	// RequestCancelled 未结算即取消，预留已全部退回。
	RequestCancelled
	// RequestPendingApproval 预估费用超过审批门槛，等待出资账户审批；
	// 此状态不冻结余额、不占用共享累计额度。
	RequestPendingApproval
	// RequestRejected 已被拒绝（审批拒绝、申请会话在等待期限内被吊销或
	// 策略被停用），终态。已到等待截止时刻后才吊销会话的请求不进入此态，
	// 而是 RequestExpired。
	RequestRejected
	// RequestExpired 待审批超过等待期限未获批准，终态。
	RequestExpired
	// RequestReservationExpired 已预留请求超过策略的最长预留时长仍未结算或
	// 取消，终态。预留已在截止时刻全额自动退回，与待审批等待过期
	// （RequestExpired）区分。
	RequestReservationExpired
)

// RequestInput 是代付申请内容。
type RequestInput struct {
	// PolicyID 指定适用策略。
	PolicyID string
	// RequestID 为使用账户维度的幂等请求编号。
	RequestID string
	// AccountID 为发起申请的使用账户。
	AccountID string
	// SessionID 为该账户绑定设备的有效会话。
	SessionID string
	// DeviceID 为当前设备，必须与会话绑定设备一致。
	DeviceID string
	// Operation 为操作类型，必须与策略一致。
	Operation string
	// Payee 为收款方，必须与策略一致。
	Payee string
	// EstimatedFee 为预估费用，必须为正，受理后按此金额预留。
	EstimatedFee int64
}

// RequestView 是代付请求的只读视图。
type RequestView struct {
	PolicyID       string
	RequestID      string
	AccountID      string
	PayerAccountID string
	Operation      string
	Payee          string
	EstimatedFee   int64
	ActualFee      int64
	State          RequestState
	CreatedAt      time.Time
	SettledAt      time.Time
	// WaitDeadline 为待审批期限（提交时刻 + 等待时长、策略结束时间、
	// 申请会话到期时间三者中的最早值）；所有走过审批流程的请求（待审批、
	// 被拒、过期、待审批取消及超门槛经批准后预留）保留该时刻，未超门槛
	// 直接预留的请求为零值。
	WaitDeadline time.Time
	// ReservedAt 为费用实际预留完成的时刻：直接受理的请求为受理时刻，
	// 批准后预留的请求为批准成功时刻。从未预留（待审批、被拒、待审批过期、
	// 待审批取消）时为零值；预留超时后仍保留该时刻。
	ReservedAt time.Time
	// ReserveDuration 为受理/批准时适用的策略最长预留时长；策略未启用预留
	// 超时（时长为零）或请求从未预留时为零。
	ReserveDuration time.Duration
	// ReserveDeadline 为启用预留超时时的截止时刻（预留时刻 + 最长预留时长）；
	// 未启用或请求从未预留时为零值。结算或取消不会改变该时刻。
	ReserveDeadline time.Time
	// ReserveExpiredAt 为预留因超时自动释放的时刻；记录的是截止时刻本身，
	// 而非稍后实际处理（查询或新申请）的时刻。尚未超时或未启用时为零值。
	ReserveExpiredAt time.Time
	// DecidedAt 为审批决定时间（批准、拒绝或过期的时刻）；未决定时为零值。
	DecidedAt time.Time
	// ApproverAccountID 为作出批准或拒绝决定的出资账户；未决定时为空。
	ApproverAccountID string
	// RejectReason 为拒绝原因（审批拒绝、会话吊销或策略停用）；未拒绝时为空。
	RejectReason string
}

// LedgerKind 标识账本记录类型。
type LedgerKind int

const (
	// LedgerReserve 预留：冻结预估费用。
	LedgerReserve LedgerKind = iota
	// LedgerSettle 扣减：结算时实际扣除的费用。
	LedgerSettle
	// LedgerRefund 退回：结算差额或取消时退回的预留。
	LedgerRefund
	// LedgerRejection 申请被拒绝或待审批被拒的留痕，不涉及任何金额变动。
	LedgerRejection
	// LedgerPendingApproval 申请进入待审批的状态留痕，无金额变动。
	LedgerPendingApproval
	// LedgerApproval 待审批被批准的状态留痕，无金额变动；批准带来的
	// 预留另记 LedgerReserve。
	LedgerApproval
	// LedgerCancellation 待审批请求被取消的状态留痕，无金额变动
	// （已预留请求的取消仍记 LedgerRefund）。
	LedgerCancellation
	// LedgerExpiration 待审批超过期限未获批准的状态留痕，无金额变动。
	LedgerExpiration
	// LedgerPolicyDeactivation 策略被出资账户主动停用的留痕，无金额变动；
	// AccountID 为出资账户，PolicyID 为被停用的策略，RequestID 为空。
	LedgerPolicyDeactivation
	// LedgerReservationExpiration 已预留请求超过最长预留时长被自动退回的
	// 状态留痕，无金额变动；AccountID 为发起申请的使用账户，关联请求编号。
	// 全额退款另记一条 LedgerRefund（AccountID 为出资账户，金额为预留全额）。
	LedgerReservationExpiration
)

// LedgerEntry 是一条账本记录。
type LedgerEntry struct {
	// Kind 为记录类型。
	Kind LedgerKind
	// AccountID 为资金发生变动的出资账户（预留、扣减、退回）；
	// 无金额变动的状态记录（待审批、批准、拒绝、取消、过期）中
	// 为发起申请的使用账户，用于关联使用账户。
	AccountID string
	// RequestID 为关联的代付请求编号。
	RequestID string
	// PolicyID 为关联的策略编号；仅策略停用等不针对具体请求的记录使用，
	// 其余记录为空（请求记录可用请求上的策略编号关联）。
	PolicyID string
	// Amount 为金额（最小货币单位，非负）；状态记录为 0。
	Amount int64
	// Reason 为拒绝原因或补充说明。
	Reason string
	At     time.Time
}

package wallet

import (
	"bytes"
	"encoding/json"
	"errors"
	"fmt"
	"io"
	"math"
	"sort"
	"time"
)

// backupVersion 为当前支持的备份格式版本号。
const backupVersion = 1

// ErrBackupInvalid 表示备份文本为空、无法解析、缺少必需数据、版本不支持
// 或内容自相矛盾。恢复接口返回包装了具体原因的错误；任何校验失败都不会
// 返回部分恢复的钱包。
var ErrBackupInvalid = errors.New("wallet: invalid backup")

// timeJSON 以 RFC3339Nano（带纳秒与时区）序列化时间，零值时间序列化为
// 空字符串，避免把“尚未发生”的计时信息误恢复成公元元年。
type timeJSON time.Time

func (t timeJSON) MarshalJSON() ([]byte, error) {
	tm := time.Time(t)
	if tm.IsZero() {
		return []byte(`""`), nil
	}
	return json.Marshal(tm.Format(time.RFC3339Nano))
}

func (t *timeJSON) UnmarshalJSON(data []byte) error {
	var s string
	if err := json.Unmarshal(data, &s); err != nil {
		return err
	}
	if s == "" {
		*t = timeJSON(time.Time{})
		return nil
	}
	tm, err := time.Parse(time.RFC3339Nano, s)
	if err != nil {
		// 宽容解析无纳秒的 RFC3339。
		tm, err = time.Parse(time.RFC3339, s)
		if err != nil {
			return err
		}
	}
	*t = timeJSON(tm)
	return nil
}

func (t timeJSON) std() time.Time { return time.Time(t) }

// durationJSON 以 int64 纳秒序列化时长，保持精确往返。
type durationJSON time.Duration

func (d durationJSON) MarshalJSON() ([]byte, error) {
	return json.Marshal(int64(d))
}

func (d *durationJSON) UnmarshalJSON(data []byte) error {
	var n int64
	if err := json.Unmarshal(data, &n); err != nil {
		return err
	}
	*d = durationJSON(n)
	return nil
}

func (d durationJSON) std() time.Duration { return time.Duration(d) }

type accountBackupV1 struct {
	ID        string   `json:"id"`
	Available int64    `json:"available"`
	Reserved  int64    `json:"reserved"`
	CreatedAt timeJSON `json:"created_at"`
}

type sessionBackupV1 struct {
	ID        string   `json:"id"`
	AccountID string   `json:"account_id"`
	DeviceID  string   `json:"device_id"`
	ExpiresAt timeJSON `json:"expires_at"`
	Revoked   bool     `json:"revoked"`
	CreatedAt timeJSON `json:"created_at"`
}

type policyBackupV1 struct {
	ID                   string       `json:"id"`
	PayerAccountID       string       `json:"payer_account_id"`
	AllowedAccountIDs    []string     `json:"allowed_account_ids"`
	Operation            string       `json:"operation"`
	Payee                string       `json:"payee"`
	StartsAt             timeJSON     `json:"starts_at"`
	EndsAt               timeJSON     `json:"ends_at"`
	MaxPerRequest        int64        `json:"max_per_request"`
	MaxTotal             int64        `json:"max_total"`
	ApprovalThreshold    int64        `json:"approval_threshold"`
	ApprovalWait         durationJSON `json:"approval_wait_nanos"`
	MaxReserveDuration   durationJSON `json:"max_reserve_duration_nanos"`
	ReservedTotal        int64        `json:"reserved_total"`
	SpentTotal           int64        `json:"spent_total"`
	Deactivated          bool         `json:"deactivated"`
	DeactivatedAt        timeJSON     `json:"deactivated_at"`
	DeactivatorAccountID string       `json:"deactivator_account_id"`
	DeactivateReason     string       `json:"deactivate_reason"`
}

type requestBackupV1 struct {
	PolicyID          string       `json:"policy_id"`
	RequestID         string       `json:"request_id"`
	AccountID         string       `json:"account_id"`
	PayerAccountID    string       `json:"payer_account_id"`
	SessionID         string       `json:"session_id"`
	Operation         string       `json:"operation"`
	Payee             string       `json:"payee"`
	EstimatedFee      int64        `json:"estimated_fee"`
	ActualFee         int64        `json:"actual_fee"`
	State             int          `json:"state"`
	CreatedAt         timeJSON     `json:"created_at"`
	SettledAt         timeJSON     `json:"settled_at"`
	WaitDeadline      timeJSON     `json:"wait_deadline"`
	ReservedAt        timeJSON     `json:"reserved_at"`
	ReserveDuration   durationJSON `json:"reserve_duration_nanos"`
	ReserveDeadline   timeJSON     `json:"reserve_deadline"`
	ReserveExpiredAt  timeJSON     `json:"reserve_expired_at"`
	DecidedAt         timeJSON     `json:"decided_at"`
	ApproverAccountID string       `json:"approver_account_id"`
	RejectReason      string       `json:"reject_reason"`
}

type ledgerEntryBackupV1 struct {
	Kind      int      `json:"kind"`
	AccountID string   `json:"account_id"`
	RequestID string   `json:"request_id"`
	PolicyID  string   `json:"policy_id"`
	Amount    int64    `json:"amount"`
	Reason    string   `json:"reason"`
	At        timeJSON `json:"at"`
}

type backupV1 struct {
	Version    int                   `json:"version"`
	ExportedAt timeJSON              `json:"exported_at"`
	Accounts   []accountBackupV1     `json:"accounts"`
	Sessions   []sessionBackupV1     `json:"sessions"`
	Policies   []policyBackupV1      `json:"policies"`
	Requests   []requestBackupV1     `json:"requests"`
	Ledger     []ledgerEntryBackupV1 `json:"ledger"`
}

// Export 将当前钱包导出为带版本号的 JSON 文本。
//
// 导出在钱包同一把全局锁内完成，对应某一时刻的完整状态：可与申请、
// 批准、拒绝、吊销、停用、结算或取消并发，不会出现只有余额变化却缺少
// 对应请求或账本的半截状态。导出前先按导出时的当前时间处理全部到期
// 请求——待审批到达等待截止时刻后进入过期终态并留痕，已预留到达预留
// 截止时刻后全额退回（释放时间仍为原截止时刻）并留下退款及超时记录；
// 未到期请求继续等待或预留。
//
// 备份保留账户余额、会话的设备绑定与吊销状态、策略条件及停用信息、
// 全部请求的申请内容、状态、审批决定与全部计时信息，以及按原顺序排列
// 的账本（包括未被受理申请的拒绝记录）。空钱包也能导出并恢复；导出
// 本身不新增任何账本记录（到期处理带来的记录除外）。
//
// 备份不能暂停期限，因此导出不改变任何请求的计时基准；导出后的钱包
// 与备份文本、以及从该备份恢复出的钱包之间互不影响。
func (w *Wallet) Export() ([]byte, error) {
	w.mu.Lock()
	defer w.mu.Unlock()

	now := w.now()
	// 导出快照前结清全部到期项，保证备份对应一个完整状态：已预留超时的按
	// 原截止时刻全额退回并留两条记录（按截止时刻排序），待审批过期的留
	// 状态记录（按等待截止时刻排序）。
	w.expireReservationsLocked(now)
	w.expirePendingApprovalsLocked(now)

	b := backupV1{
		Version:    backupVersion,
		ExportedAt: timeJSON(now),
		Accounts:   make([]accountBackupV1, 0, len(w.accounts)),
		Sessions:   make([]sessionBackupV1, 0, len(w.sessions)),
		Policies:   make([]policyBackupV1, 0, len(w.policies)),
		Requests:   make([]requestBackupV1, 0, len(w.requests)),
		Ledger:     make([]ledgerEntryBackupV1, 0, len(w.ledger)),
	}

	// map 迭代顺序不确定；集合类数据按编号排序，使备份可逐字节复现。
	for _, a := range w.accounts {
		b.Accounts = append(b.Accounts, accountBackupV1{
			ID:        a.id,
			Available: a.available,
			Reserved:  a.reserved,
			CreatedAt: timeJSON(a.createdAt),
		})
	}
	sort.Slice(b.Accounts, func(i, j int) bool { return b.Accounts[i].ID < b.Accounts[j].ID })

	for _, s := range w.sessions {
		b.Sessions = append(b.Sessions, sessionBackupV1{
			ID:        s.id,
			AccountID: s.accountID,
			DeviceID:  s.deviceID,
			ExpiresAt: timeJSON(s.expiresAt),
			Revoked:   s.revoked,
			CreatedAt: timeJSON(s.createdAt),
		})
	}
	sort.Slice(b.Sessions, func(i, j int) bool { return b.Sessions[i].ID < b.Sessions[j].ID })

	for _, p := range w.policies {
		allowed := make([]string, 0, len(p.allowedAccounts))
		for id := range p.allowedAccounts {
			allowed = append(allowed, id)
		}
		sort.Strings(allowed)
		b.Policies = append(b.Policies, policyBackupV1{
			ID:                   p.id,
			PayerAccountID:       p.payerAccountID,
			AllowedAccountIDs:    allowed,
			Operation:            p.operation,
			Payee:                p.payee,
			StartsAt:             timeJSON(p.startsAt),
			EndsAt:               timeJSON(p.endsAt),
			MaxPerRequest:        p.maxPerRequest,
			MaxTotal:             p.maxTotal,
			ApprovalThreshold:    p.approvalThreshold,
			ApprovalWait:         durationJSON(p.approvalWait),
			MaxReserveDuration:   durationJSON(p.maxReserveDuration),
			ReservedTotal:        p.reservedTotal,
			SpentTotal:           p.spentTotal,
			Deactivated:          p.deactivated,
			DeactivatedAt:        timeJSON(p.deactivatedAt),
			DeactivatorAccountID: p.deactivatorAccountID,
			DeactivateReason:     p.deactivateReason,
		})
	}
	sort.Slice(b.Policies, func(i, j int) bool { return b.Policies[i].ID < b.Policies[j].ID })

	for _, r := range w.requests {
		b.Requests = append(b.Requests, requestBackupV1{
			PolicyID:          r.policyID,
			RequestID:         r.requestID,
			AccountID:         r.accountID,
			PayerAccountID:    r.payerAccountID,
			SessionID:         r.sessionID,
			Operation:         r.operation,
			Payee:             r.payee,
			EstimatedFee:      r.estimatedFee,
			ActualFee:         r.actualFee,
			State:             int(r.state),
			CreatedAt:         timeJSON(r.createdAt),
			SettledAt:         timeJSON(r.settledAt),
			WaitDeadline:      timeJSON(r.waitDeadline),
			ReservedAt:        timeJSON(r.reservedAt),
			ReserveDuration:   durationJSON(r.reserveDuration),
			ReserveDeadline:   timeJSON(r.reserveDeadline),
			ReserveExpiredAt:  timeJSON(r.reserveExpiredAt),
			DecidedAt:         timeJSON(r.decidedAt),
			ApproverAccountID: r.approverAccountID,
			RejectReason:      r.rejectReason,
		})
	}
	sort.Slice(b.Requests, func(i, j int) bool {
		if b.Requests[i].AccountID != b.Requests[j].AccountID {
			return b.Requests[i].AccountID < b.Requests[j].AccountID
		}
		return b.Requests[i].RequestID < b.Requests[j].RequestID
	})

	// 账本严格按原顺序导出，不重新排序。
	for _, e := range w.ledger {
		b.Ledger = append(b.Ledger, ledgerEntryBackupV1{
			Kind:      int(e.Kind),
			AccountID: e.AccountID,
			RequestID: e.RequestID,
			PolicyID:  e.PolicyID,
			Amount:    e.Amount,
			Reason:    e.Reason,
			At:        timeJSON(e.At),
		})
	}

	out, err := json.Marshal(&b)
	if err != nil {
		return nil, fmt.Errorf("%w: encode: %v", ErrBackupInvalid, err)
	}
	return out, nil
}

// addInt64 在求和时检测 int64 溢出；超出范围返回 false。
func addInt64(sum, x int64) (int64, bool) {
	if x > 0 && sum > math.MaxInt64-x {
		return 0, false
	}
	if x < 0 && sum < math.MinInt64-x {
		return 0, false
	}
	return sum + x, true
}

// Restore 从 Export 产生的 JSON 文本创建一个独立的钱包。
//
// 恢复不重新计时：所有截止时刻与会话到期时间沿用备份中的绝对时刻，
// 恢复前先按恢复时的当前时间处理全部到期请求（待审批过期、已预留超时
// 全额退回，释放时间仍为原截止时刻）。既有终态与历史记录不改写；过期或
// 吊销的会话、停用或结束的策略可以恢复，但不会重新获得授权。恢复后被
// 超时退回的余额可立即用于新申请，旧请求的迟到结算不能再扣走这笔钱。
//
// 空文本、非法 JSON、缺少必需数据、不支持的版本、编号重复、未知状态或
// 账本类型、非法金额或策略参数、悬空引用、申请会话不属于使用账户、
// 请求出资账户与策略不符，或余额/累计金额与请求求和不一致（含求和超出
// int64 范围），都返回包装了具体原因的 ErrBackupInvalid，绝不会返回
// 部分恢复的钱包。每笔已受理请求记载的提交时刻还必须落在关联策略的时间
// 窗内且不晚于申请会话到期：不早于策略开始时刻（恰在开始时刻提交可以
// 接受）、严格早于策略结束时刻、严格早于申请会话到期时刻（恰在策略结束
// 或会话到期时提交必须拒绝）；正常提交时这些时刻的申请本就会被拒绝，
// 不可能成为已受理请求。直接预留与经过审批的申请适用同一规则，后来已
// 结算、取消、拒绝或过期的请求也不豁免；该核对只针对备份记载的提交历史，
// 不以恢复时的当前时间替代，因此申请当时符合条件、之后会话到期或被吊销、
// 策略结束或被停用的请求仍按现有规则恢复。未被受理的申请留下的独立拒绝
// 账本记录不关联请求，不适用本规则，仍原样保留。曾经批准成功并实际预留费用的超门槛请求（恢复时仍为
// 已预留，或后来已结算、已取消、已预留超时）还必须通过审批时限核对：
// 保存的等待截止时刻必须与提交时刻加策略等待时长、策略结束时间、申请
// 会话到期时间三者的最早值一致（缺失、提前、推迟都拒绝），且批准决定
// 必须发生在提交时刻及之后、等待截止时刻之前（恰在提交时刻批准可以
// 接受，恰到截止时刻批准必须拒绝）；该核对只针对备份记载的批准历史，
// 不以恢复时的当前时间替代批准时间，因此期限内已批准的请求即使恢复时
// 等待期限、申请会话或策略时间窗均已结束也照常恢复，不重新计时。
// 已拒绝请求（出资账户主动拒绝、申请会话吊销或策略停用导致，原因与决定
// 账户的区别保留）同样必须通过拒绝时限核对：保存的等待截止时刻必须存在，
// 并与提交时刻加策略最长等待时长、策略结束时刻、申请会话到期时刻三者的
// 最早值一致（缺失、提前、推迟都拒绝），且拒绝决定必须发生在提交时刻及
// 之后、等待截止时刻之前（提交当时立即拒绝可以接受，截止当时才拒绝必须
// 拒绝）；该核对只看备份记载的申请与拒绝历史，与恢复时的当前时间无关，
// 因此期限内完成的合法拒绝即使恢复时会话已到期或被吊销、策略已结束或
// 停用，仍保持已拒绝原样恢复，不追加过期记录、不产生资金变动。余额与
// 策略累计金额核对一致也不能让时间矛盾的备份通过。
// 曾在待审批状态取消、从未预留费用的请求（已预留后再取消的沿用既有规则，
// 不因缺少待审批取消的决定时间被拒绝）同样必须通过取消时限核对：保存的
// 等待截止时刻必须存在，并与提交时刻加策略等待时长、策略结束时间、申请
// 会话到期时间三者的最早值一致（缺失、提前、推迟都拒绝，哪怕保存的取消
// 时间仍落在修改后的期限内），且取消决定必须发生在提交时刻及之后、等待
// 截止时刻之前（提交当时就取消可以接受，恰到截止时刻或更晚取消必须拒绝；
// 策略结束或会话到期先发生时按最早的那个时刻判断，不能只用最长等待时长）。
// 该核对只看备份记载的申请与取消历史，与恢复时的当前时间无关，因此期限内
// 完成的合法取消即使很久以后才恢复、申请会话已过期或吊销、策略已结束或
// 停用，仍保持原取消状态、决定时间与账本顺序，不追加过期或退款记录，不
// 冻结余额、不占用额度；矛盾的已取消记录不会被自动改成过期来接受备份。
// 此外，任一仍处于待审批状态的请求都不得关联已吊销的申请会话：主动吊销
// 申请会话时，吊销发生在等待截止时刻之前的待审批请求会立即进入拒绝终态，
// 恰到或超过截止时刻的进入过期终态，二者皆终态，不可能继续等待出资账户
// 批准。因此备份保存的“申请会话已吊销 + 请求仍待审批”自相矛盾，只要存在
// 一笔即整体拒绝恢复（错误指出使用账户、请求编号与申请会话编号，并说明
// 已吊销会话不能保留待审批请求），哪怕该请求的账户、会话归属、策略、费用、
// 等待期限符合其他全部校验、账户与策略金额核对一致，即使同一备份的其他
// 会话与请求均合法也不能放行。该判断只针对备份保存的会话吊销标记与请求
// 状态、不随恢复时刻改变：等待期限尚未到达、恰好到达或早已过去都得到相同
// 的备份无效结果；恢复时不会先把该请求按当前时间自动变成过期再接受备份，
// 也不替调用方补写吊销拒绝决定、猜测吊销时间、清除吊销标记或删除请求来
// 消除矛盾。判断按提交申请所用的会话进行：出资账户用于审批的会话有效也
// 不能使矛盾备份恢复成功。已吊销会话本身及其全部合法历史仍可恢复：吊销前
// 已预留的请求继续按原规则结算、取消或等待预留超时；吊销产生的拒绝（期限
// 内吊销）或过期（恰到或超过期限吊销）请求，以及已经结算、取消的历史，
// 保留原状态、金额、决定信息与既有账本；未吊销会话下的合法待审批请求仍可
// 恢复并继续审批，到期时按原规则过期。独立的申请拒绝账本记录不关联请求，
// 不受此规则影响。
// 此外，任一仍处于待审批状态的请求都不得关联已停用策略：正常停用时该策略
// 下未到等待期限的待审批请求会立即进入拒绝终态、已到（含恰到）或超过期限
// 的进入过期终态，二者皆终态，不可能继续等待出资账户批准。因此备份保存的
// “已停用策略 + 待审批请求”自相矛盾，只要存在一笔即整体拒绝恢复（错误指出
// 使用账户、请求编号与策略编号，并说明已停用策略不能保留待审批请求），哪怕
// 该请求的账户与会话引用、审批门槛、等待截止时刻、账户与策略金额都符合其他
// 全部校验，即使同一备份的其他策略与请求均合法也不能放行。该判断只针对备份
// 保存的状态、不随恢复时刻改变：等待期限尚未到达、恰好到达或早已过去都得到
// 相同的备份无效结果；恢复时不会先把该请求自动变成过期再接受备份，也不替
// 调用方补写停用拒绝记录、清除停用标志或改写请求来消除矛盾。已停用策略本身
// 及其全部合法历史仍可恢复：停用前已预留的请求继续按原规则结算、取消或等待
// 预留超时；已结算、已取消、已拒绝或已过期的请求保留原状态与决定信息；策略
// 的首次停用时间、执行账户、理由、余额与已有账本顺序原样保留；未停用策略下
// 的合法待审批请求仍可恢复并继续审批，到期时按原规则过期。
// 从未预留费用、因等待审批到期进入已过期终态的请求（已预留费用的预留超时
// 不适用）同样必须通过过期时限核对：保存的等待截止时刻必须存在，并与提交
// 时刻加策略最长等待时长、策略结束时间、申请会话到期时间三者的最早值一致
// （缺失、提前、推迟都拒绝，即使修改后的截止时刻仍早于记载的过期决定；
// 策略或会话更早到期时按最早的那个时刻判断，不能只按最长等待时长），且
// 过期决定时刻必须存在、不早于该截止时刻（恰到截止时刻发现过期可以接受，
// 早于它必须拒绝）。钱包可能在到期很久后才发现请求过期，合法决定时刻不必
// 等于截止时刻，恢复时不改写为截止时刻或当前时间。该核对只看备份记载的
// 申请与过期历史，与恢复时的当前时间无关，因此合法过期即使恢复时会话已
// 到期或被吊销、策略已结束或停用，仍保持原过期状态、全部时刻与账本顺序，
// 不追加过期记录，不产生预留、扣减或退款。
// 曾经完成结算的请求（直接受理与批准后预留两条路径一致）还必须通过结算
// 时刻核对：启用预留超时时，结算时刻必须不早于实际预留时刻且严格早于预留
// 截止时刻（恰在预留完成时结算可以接受，恰到截止时刻及之后必须拒绝，实际
// 费用为零也不例外）；时间按备份保存的完整绝对时刻比较，纳秒与时区表示均
// 不改变结论，关闭预留超时的请求不设此项期限。该核对同样只看备份记载的
// 预留与结算时刻，与恢复时的当前时间无关：期限内完成的结算即使很久以后恢复
// 仍保持已结算，余额、策略已花费总额与既有账本原样保留，不追加退款或超时
// 记录。
// 未经审批直接受理的请求（策略关闭审批，或预估费用未严格超过审批门槛）
// 只要曾经预留过费用（恢复时仍为已预留，或后来已结算、已取消、已预留超时），
// 实际预留时刻还必须与提交时刻是同一瞬间：正常申请无需审批时，提交成功即
// 同时完成费用预留。预留起点提前或推迟均拒绝，即使只差一纳秒；两种带不同
// 时区的时间写法若表示同一绝对时刻则正常接受。关闭预留超时的策略同样适用，
// 不允许预留起点与提交时刻脱离。该核对只针对备份记载的提交与预留时刻，与
// 恢复时的当前时间无关：即使被篡改的预留截止时刻在恢复时已经过去，也必须
// 整体拒绝，不能先按超时退款、再把矛盾历史当成合法备份。经大额审批后才
// 预留的请求不受此限，其实际预留时刻为批准成功时刻、允许晚于提交时刻，
// 由上方的审批时限核对覆盖。
// 任一策略现存预留费用与已结算实际费用的合计严格超过其
// 共享累计上限时同样拒绝（同一策略的多个使用账户合并计算，不同策略分别
// 判断；待审批、已取消、被拒绝、已过期及预留超时的请求不占用额度），
// 该检查针对备份保存的资金占用状态、在恢复时的到期自动退回之前完成：
// 合计恰好等于上限合法，上限恰为 MaxInt64 时也不缩小可接受的金额范围。
// 任一账户的可用余额加上该账户在所有策略下仍处于已预留
// 状态的费用之和超出 int64 上限时同样拒绝（即使各请求、各策略金额分别
// 合法）：否则取消或预留超时的退回会使余额越界；校验在恢复时的到期
// 自动退回之前完成，预留尚未到期也当场拒绝。恢复出的钱包与原钱包、同一
// 备份恢复出的其他钱包互不影响。
func Restore(data []byte) (*Wallet, error) {
	if len(bytes.TrimSpace(data)) == 0 {
		return nil, fmt.Errorf("%w: empty backup", ErrBackupInvalid)
	}

	var b backupV1
	dec := json.NewDecoder(bytes.NewReader(data))
	if err := dec.Decode(&b); err != nil {
		return nil, fmt.Errorf("%w: malformed json: %v", ErrBackupInvalid, err)
	}
	// 不允许备份对象之后还有多余的 JSON 值；忽略空白。
	if _, err := dec.Token(); err != io.EOF {
		return nil, fmt.Errorf("%w: unexpected trailing data after backup object", ErrBackupInvalid)
	}
	if b.Version != backupVersion {
		return nil, fmt.Errorf("%w: unsupported version %d (supported: %d)", ErrBackupInvalid, b.Version, backupVersion)
	}

	w := New()
	if err := w.restoreLocked(&b); err != nil {
		return nil, err
	}
	return w, nil
}

// restoreAt 仅供同包测试使用：与 Restore 相同，但显式指定恢复时刻，
// 便于确定性地验证恢复时的到期处理。
func restoreAt(data []byte, now time.Time) (*Wallet, error) {
	if len(bytes.TrimSpace(data)) == 0 {
		return nil, fmt.Errorf("%w: empty backup", ErrBackupInvalid)
	}
	var b backupV1
	dec := json.NewDecoder(bytes.NewReader(data))
	if err := dec.Decode(&b); err != nil {
		return nil, fmt.Errorf("%w: malformed json: %v", ErrBackupInvalid, err)
	}
	if _, err := dec.Token(); err != io.EOF {
		return nil, fmt.Errorf("%w: unexpected trailing data after backup object", ErrBackupInvalid)
	}
	if b.Version != backupVersion {
		return nil, fmt.Errorf("%w: unsupported version %d (supported: %d)", ErrBackupInvalid, b.Version, backupVersion)
	}
	w := New()
	w.now = func() time.Time { return now }
	if err := w.restoreLocked(&b); err != nil {
		return nil, err
	}
	return w, nil
}

// restoreLocked 逐段构建并校验新钱包；任何失败都返回错误，调用方因此
// 绝不会拿到部分恢复的钱包。
func (w *Wallet) restoreLocked(b *backupV1) error {
	// ---- 账户 ----
	if b.Accounts == nil {
		return fmt.Errorf("%w: missing accounts", ErrBackupInvalid)
	}
	accountIDs := make(map[string]struct{}, len(b.Accounts))
	reservedByAccount := make(map[string]int64)
	for i, a := range b.Accounts {
		if a.ID == "" {
			return fmt.Errorf("%w: account[%d] has empty id", ErrBackupInvalid, i)
		}
		if _, dup := accountIDs[a.ID]; dup {
			return fmt.Errorf("%w: duplicate account id %q", ErrBackupInvalid, a.ID)
		}
		if a.Available < 0 {
			return fmt.Errorf("%w: account %q available balance is negative: %d", ErrBackupInvalid, a.ID, a.Available)
		}
		if a.Reserved < 0 {
			return fmt.Errorf("%w: account %q reserved balance is negative: %d", ErrBackupInvalid, a.ID, a.Reserved)
		}
		accountIDs[a.ID] = struct{}{}
		w.accounts[a.ID] = &account{
			id:        a.ID,
			available: a.Available,
			reserved:  a.Reserved,
			createdAt: a.CreatedAt.std(),
		}
	}

	// ---- 会话 ----
	if b.Sessions == nil {
		return fmt.Errorf("%w: missing sessions", ErrBackupInvalid)
	}
	sessionByID := make(map[string]*session, len(b.Sessions))
	for i, s := range b.Sessions {
		if s.ID == "" {
			return fmt.Errorf("%w: session[%d] has empty id", ErrBackupInvalid, i)
		}
		if _, dup := sessionByID[s.ID]; dup {
			return fmt.Errorf("%w: duplicate session id %q", ErrBackupInvalid, s.ID)
		}
		if s.AccountID == "" || s.DeviceID == "" {
			return fmt.Errorf("%w: session %q missing account or device id", ErrBackupInvalid, s.ID)
		}
		if _, ok := accountIDs[s.AccountID]; !ok {
			return fmt.Errorf("%w: session %q references unknown account %q", ErrBackupInvalid, s.ID, s.AccountID)
		}
		sess := &session{
			id:        s.ID,
			accountID: s.AccountID,
			deviceID:  s.DeviceID,
			expiresAt: s.ExpiresAt.std(),
			revoked:   s.Revoked,
			createdAt: s.CreatedAt.std(),
		}
		sessionByID[s.ID] = sess
		w.sessions[s.ID] = sess
	}

	// ---- 策略 ----
	if b.Policies == nil {
		return fmt.Errorf("%w: missing policies", ErrBackupInvalid)
	}
	policyByID := make(map[string]*policy, len(b.Policies))
	for i, p := range b.Policies {
		if p.ID == "" {
			return fmt.Errorf("%w: policy[%d] has empty id", ErrBackupInvalid, i)
		}
		if _, dup := policyByID[p.ID]; dup {
			return fmt.Errorf("%w: duplicate policy id %q", ErrBackupInvalid, p.ID)
		}
		if err := validatePolicyParams(p); err != nil {
			return fmt.Errorf("%w: policy %q: %v", ErrBackupInvalid, p.ID, err)
		}
		if _, ok := accountIDs[p.PayerAccountID]; !ok {
			return fmt.Errorf("%w: policy %q references unknown payer account %q", ErrBackupInvalid, p.ID, p.PayerAccountID)
		}
		allowed := make(map[string]struct{}, len(p.AllowedAccountIDs))
		for j, id := range p.AllowedAccountIDs {
			if id == "" {
				return fmt.Errorf("%w: policy %q allowed account[%d] is empty", ErrBackupInvalid, p.ID, j)
			}
			if _, ok := accountIDs[id]; !ok {
				return fmt.Errorf("%w: policy %q references unknown allowed account %q", ErrBackupInvalid, p.ID, id)
			}
			if _, dup := allowed[id]; dup {
				return fmt.Errorf("%w: policy %q lists allowed account %q more than once", ErrBackupInvalid, p.ID, id)
			}
			allowed[id] = struct{}{}
		}
		if p.ReservedTotal < 0 || p.SpentTotal < 0 {
			return fmt.Errorf("%w: policy %q totals must not be negative (reserved %d spent %d)", ErrBackupInvalid, p.ID, p.ReservedTotal, p.SpentTotal)
		}
		po := &policy{
			id:                   p.ID,
			payerAccountID:       p.PayerAccountID,
			allowedAccounts:      allowed,
			operation:            p.Operation,
			payee:                p.Payee,
			startsAt:             p.StartsAt.std(),
			endsAt:               p.EndsAt.std(),
			maxPerRequest:        p.MaxPerRequest,
			maxTotal:             p.MaxTotal,
			approvalThreshold:    p.ApprovalThreshold,
			approvalWait:         p.ApprovalWait.std(),
			maxReserveDuration:   p.MaxReserveDuration.std(),
			reservedTotal:        p.ReservedTotal,
			spentTotal:           p.SpentTotal,
			deactivated:          p.Deactivated,
			deactivatedAt:        p.DeactivatedAt.std(),
			deactivatorAccountID: p.DeactivatorAccountID,
			deactivateReason:     p.DeactivateReason,
		}
		// 停用信息自洽：停用标志必须与停用时间/理由同时出现；停用账户必须
		// 存在；未停用不得携带任何停用记录。
		if po.deactivated {
			if po.deactivatedAt.IsZero() || po.deactivateReason == "" {
				return fmt.Errorf("%w: policy %q marked deactivated but missing deactivation time or reason", ErrBackupInvalid, p.ID)
			}
			if po.deactivatorAccountID != "" {
				if _, ok := accountIDs[po.deactivatorAccountID]; !ok {
					return fmt.Errorf("%w: policy %q deactivator references unknown account %q", ErrBackupInvalid, p.ID, po.deactivatorAccountID)
				}
			}
		} else if !po.deactivatedAt.IsZero() || po.deactivatorAccountID != "" || po.deactivateReason != "" {
			return fmt.Errorf("%w: policy %q not deactivated but carries deactivation info", ErrBackupInvalid, p.ID)
		}
		policyByID[p.ID] = po
		w.policies[p.ID] = po
	}

	// ---- 请求 ----
	if b.Requests == nil {
		return fmt.Errorf("%w: missing requests", ErrBackupInvalid)
	}
	reqKeys := make(map[requestKey]struct{}, len(b.Requests))
	reservedSumByPolicy := make(map[string]int64)
	spentSumByPolicy := make(map[string]int64)
	for i, r := range b.Requests {
		if err := validateRequestRef(r, i, accountIDs, sessionByID, policyByID); err != nil {
			return err
		}
		key := requestKey{accountID: r.AccountID, requestID: r.RequestID}
		if _, dup := reqKeys[key]; dup {
			return fmt.Errorf("%w: duplicate request id %q under account %q", ErrBackupInvalid, r.RequestID, r.AccountID)
		}
		reqKeys[key] = struct{}{}

		state := RequestState(r.State)
		if state < RequestReserved || state > RequestReservationExpired {
			return fmt.Errorf("%w: request %q/%q has unknown state %d", ErrBackupInvalid, r.AccountID, r.RequestID, r.State)
		}
		if r.EstimatedFee <= 0 {
			return fmt.Errorf("%w: request %q/%q estimated fee must be positive: %d", ErrBackupInvalid, r.AccountID, r.RequestID, r.EstimatedFee)
		}
		if r.ActualFee < 0 {
			return fmt.Errorf("%w: request %q/%q actual fee is negative: %d", ErrBackupInvalid, r.AccountID, r.RequestID, r.ActualFee)
		}
		if r.ReserveDuration.std() < 0 {
			return fmt.Errorf("%w: request %q/%q reserve duration is negative", ErrBackupInvalid, r.AccountID, r.RequestID)
		}

		req := &request{
			policyID:          r.PolicyID,
			requestID:         r.RequestID,
			accountID:         r.AccountID,
			payerAccountID:    r.PayerAccountID,
			sessionID:         r.SessionID,
			operation:         r.Operation,
			payee:             r.Payee,
			estimatedFee:      r.EstimatedFee,
			actualFee:         r.ActualFee,
			state:             state,
			createdAt:         r.CreatedAt.std(),
			settledAt:         r.SettledAt.std(),
			waitDeadline:      r.WaitDeadline.std(),
			reservedAt:        r.ReservedAt.std(),
			reserveDuration:   r.ReserveDuration.std(),
			reserveDeadline:   r.ReserveDeadline.std(),
			reserveExpiredAt:  r.ReserveExpiredAt.std(),
			decidedAt:         r.DecidedAt.std(),
			approverAccountID: r.ApproverAccountID,
			rejectReason:      r.RejectReason,
		}
		if err := validateRequestTimingAndState(req, policyByID[r.PolicyID], sessionByID[r.SessionID]); err != nil {
			return fmt.Errorf("%w: request %q/%q: %v", ErrBackupInvalid, r.AccountID, r.RequestID, err)
		}
		w.requests[key] = req

		// 累加各账户/策略“按请求推算”的金额，稍后与快照余额核对。
		// 只有当前仍处于已预留的请求才占用账户预留与策略预留总额。
		if state == RequestReserved {
			sum, ok := addInt64(reservedByAccount[req.payerAccountID], req.estimatedFee)
			if !ok {
				return fmt.Errorf("%w: account %q reserved sum overflows int64", ErrBackupInvalid, req.payerAccountID)
			}
			reservedByAccount[req.payerAccountID] = sum
			sum, ok = addInt64(reservedSumByPolicy[req.policyID], req.estimatedFee)
			if !ok {
				return fmt.Errorf("%w: policy %q reserved sum overflows int64", ErrBackupInvalid, req.policyID)
			}
			reservedSumByPolicy[req.policyID] = sum
		}
		if state == RequestSettled {
			sum, ok := addInt64(spentSumByPolicy[req.policyID], req.actualFee)
			if !ok {
				return fmt.Errorf("%w: policy %q spent sum overflows int64", ErrBackupInvalid, req.policyID)
			}
			spentSumByPolicy[req.policyID] = sum
		}
	}

	// ---- 账户预留余额 == 已预留请求预估费用之和 ----
	for id, acc := range w.accounts {
		if got, want := acc.reserved, reservedByAccount[id]; got != want {
			return fmt.Errorf("%w: account %q reserved %d != sum of reserved requests %d", ErrBackupInvalid, id, got, want)
		}
	}

	// ---- 可用余额 + 现存预留不得超过 int64 上限 ----
	// 取消或预留超时会把预留全额退回可用余额：合计一旦超出 MaxInt64，
	// 退回时余额就会越界变负。reservedByAccount 按出资账户汇总该账户在
	// 所有策略下仍处于已预留状态的费用（待审批不冻结费用，已结算、已取消、
	// 已预留超时的费用不再占用预留，故均不计入）。本检查必须在恢复时的
	// 到期自动退回之前完成，使“恢复即超时退款”的备份也不能蒙混过关；
	// 合计恰好等于上限合法（随后退回恰好得到上限金额）。
	for id, acc := range w.accounts {
		if _, ok := addInt64(acc.available, reservedByAccount[id]); !ok {
			return fmt.Errorf("%w: account %q available %d plus reserved %d overflows int64", ErrBackupInvalid, id, acc.available, reservedByAccount[id])
		}
	}

	// ---- 策略预留总额/已花费总额 == 请求求和，且合计不得超过累计上限 ----
	// 现存预留费用与已结算的实际费用共同占用策略的共享累计额度；同一策略的
	// 多个使用账户合计判断，不同策略分别判断。待审批不冻结费用，已取消、被
	// 拒绝、待审批过期、预留超时的请求均不计入，故上方求和本就不含它们。
	// 严格超过累计上限的备份自相矛盾（正常流程在受理时就会拒绝），必须整体
	// 拒绝；合计恰好等于上限合法。本检查针对备份保存的资金占用状态，位于
	// 恢复时的到期自动退回之前：即使某笔已预留请求恢复时已到期、将全额
	// 退回，也不能先退回再让原本超额的备份通过。两项金额各自为 int64、
	// 合计越过 int64 上限时，addInt64 先捕获溢出，不能误判为额度充足。
	for id, p := range policyByID {
		if got, want := p.reservedTotal, reservedSumByPolicy[id]; got != want {
			return fmt.Errorf("%w: policy %q reserved total %d != sum of reserved requests %d", ErrBackupInvalid, id, got, want)
		}
		if got, want := p.spentTotal, spentSumByPolicy[id]; got != want {
			return fmt.Errorf("%w: policy %q spent total %d != sum of settled requests %d", ErrBackupInvalid, id, got, want)
		}
		used, ok := addInt64(reservedSumByPolicy[id], spentSumByPolicy[id])
		if !ok {
			return fmt.Errorf("%w: policy %q reserved %d plus spent %d overflows int64 and exceeds cumulative total limit %d",
				ErrBackupInvalid, id, reservedSumByPolicy[id], spentSumByPolicy[id], p.maxTotal)
		}
		if used > p.maxTotal {
			return fmt.Errorf("%w: policy %q reserved %d plus spent %d exceeds cumulative total limit %d",
				ErrBackupInvalid, id, reservedSumByPolicy[id], spentSumByPolicy[id], p.maxTotal)
		}
	}

	// ---- 账本 ----
	if b.Ledger == nil {
		return fmt.Errorf("%w: missing ledger", ErrBackupInvalid)
	}
	w.ledger = make([]LedgerEntry, 0, len(b.Ledger))
	for i, e := range b.Ledger {
		kind := LedgerKind(e.Kind)
		if kind < LedgerReserve || kind > LedgerReservationExpiration {
			return fmt.Errorf("%w: ledger[%d] has unknown kind %d", ErrBackupInvalid, i, e.Kind)
		}
		if e.Amount < 0 {
			return fmt.Errorf("%w: ledger[%d] amount is negative: %d", ErrBackupInvalid, i, e.Amount)
		}
		// 账本是历史留痕：其账户/请求编号允许为空或指向不存在的实体。
		// 未被受理申请（必填字段缺失、使用账户或会话不存在等）同样会留下
		// 拒绝记录，这些记录必须原样保留，不能因为找不到对应账户或请求而
		// 丢弃或拒绝恢复。资金一致性由账户余额与现存请求的求和核对保证，
		// 不依赖账本文本。PolicyID 若给出则必须存在（仅策略停用记录使用）。
		if e.PolicyID != "" {
			if _, ok := policyByID[e.PolicyID]; !ok {
				return fmt.Errorf("%w: ledger[%d] references unknown policy %q", ErrBackupInvalid, i, e.PolicyID)
			}
		}
		w.ledger = append(w.ledger, LedgerEntry{
			Kind:      kind,
			AccountID: e.AccountID,
			RequestID: e.RequestID,
			PolicyID:  e.PolicyID,
			Amount:    e.Amount,
			Reason:    e.Reason,
			At:        e.At.std(),
		})
	}

	// ---- 恢复时按当前时间结清到期请求（不重新计时，只推进惰性状态） ----
	// 处理顺序与导出保持一致：先释放已到期预留，再把到期的待审批转为过期，
	// 两类记录均按各自截止时刻排序后追加到账本末尾。
	now := w.now()
	w.expireReservationsLocked(now)
	w.expirePendingApprovalsLocked(now)
	return nil
}

// validatePolicyParams 校验备份中策略的条件与限额参数，与 SavePolicy 共用
// validatePolicySpecParams 的同一套判断，恢复时不再单独维护一份规则。
// 备份特有的编号、编号重复、账户存在性与授权账户重复列出检查仍由
// restoreLocked 按恢复口径另行处理（备份中同一策略重复列出授权账户必须
// 拒绝，不能像保存入口那样按同一账户处理）。
//
// 关闭审批（门槛为零）时等待时长不被使用，备份保存的原值（正、零、负
// 均可）必须原样接受，不能因为未使用的等待设置拒绝整个钱包；最长预留
// 时长是独立设置，即使关闭审批也不得为负——这些关系由共用的参数判断
// 保证，与保存入口一致。
func validatePolicyParams(p policyBackupV1) error {
	return validatePolicySpecParams(PolicySpec{
		PayerAccountID:     p.PayerAccountID,
		AllowedAccountIDs:  p.AllowedAccountIDs,
		Operation:          p.Operation,
		Payee:              p.Payee,
		StartsAt:           p.StartsAt.std(),
		EndsAt:             p.EndsAt.std(),
		MaxPerRequest:      p.MaxPerRequest,
		MaxTotal:           p.MaxTotal,
		ApprovalThreshold:  p.ApprovalThreshold,
		ApprovalWait:       p.ApprovalWait.std(),
		MaxReserveDuration: p.MaxReserveDuration.std(),
	})
}

// validateRequestRef 校验请求的外键引用：账户、会话、策略均须存在；申请
// 会话必须属于使用账户；出资账户必须与策略一致；申请账户必须被策略允许。
func validateRequestRef(r requestBackupV1, i int, accounts map[string]struct{}, sessions map[string]*session, policies map[string]*policy) error {
	where := fmt.Sprintf("request[%d] %q/%q", i, r.AccountID, r.RequestID)
	if r.RequestID == "" || r.AccountID == "" || r.PolicyID == "" || r.SessionID == "" {
		return fmt.Errorf("%w: %s missing required id (account/request/policy/session)", ErrBackupInvalid, where)
	}
	if _, ok := accounts[r.AccountID]; !ok {
		return fmt.Errorf("%w: %s references unknown usage account %q", ErrBackupInvalid, where, r.AccountID)
	}
	if _, ok := accounts[r.PayerAccountID]; !ok {
		return fmt.Errorf("%w: %s references unknown payer account %q", ErrBackupInvalid, where, r.PayerAccountID)
	}
	sess, ok := sessions[r.SessionID]
	if !ok {
		return fmt.Errorf("%w: %s references unknown session %q", ErrBackupInvalid, where, r.SessionID)
	}
	// 申请会话必须属于使用账户。
	if sess.accountID != r.AccountID {
		return fmt.Errorf("%w: %s session %q belongs to account %q, not usage account %q", ErrBackupInvalid, where, r.SessionID, sess.accountID, r.AccountID)
	}
	p, ok := policies[r.PolicyID]
	if !ok {
		return fmt.Errorf("%w: %s references unknown policy %q", ErrBackupInvalid, where, r.PolicyID)
	}
	// 请求出资账户必须与策略出资账户一致。
	if r.PayerAccountID != p.payerAccountID {
		return fmt.Errorf("%w: %s payer account %q does not match policy %q payer %q", ErrBackupInvalid, where, r.PayerAccountID, r.PolicyID, p.payerAccountID)
	}
	if _, ok := p.allowedAccounts[r.AccountID]; !ok {
		return fmt.Errorf("%w: %s usage account %q is not allowed by policy %q", ErrBackupInvalid, where, r.AccountID, r.PolicyID)
	}
	return nil
}

// validateReserveTiming 校验预留计时三元组自洽：duration 必须非负；
// duration>0 时 reservedAt 必填且 reserveDeadline 必须等于
// reservedAt+duration；duration==0 时 reserveDeadline 必须为零。
// reservedAt 是否必填由各状态自行决定（待审批取消的请求两者都没有）。
func validateReserveTiming(r *request) error {
	if r.reserveDuration < 0 {
		return errors.New("reserve duration must not be negative")
	}
	if r.reserveDuration > 0 {
		if r.reservedAt.IsZero() {
			return errors.New("reserve duration set but reserved_at is missing")
		}
		want := r.reservedAt.Add(r.reserveDuration)
		if !r.reserveDeadline.Equal(want) {
			return fmt.Errorf("reserve deadline %v does not match reserved_at+duration %v", r.reserveDeadline, want)
		}
	} else if !r.reserveDeadline.IsZero() {
		return errors.New("reserve deadline set while reserve duration is zero")
	}
	return nil
}

// validateSettlementTiming 校验已结算请求的结算时刻必须是正常结算能够产生的
// 历史：不早于实际预留时刻（恰在预留完成时结算可以接受）；当请求启用了预留
// 超时（reserveDuration>0，此时 reserveDeadline 已由 validateReserveTiming
// 确认为 reservedAt+duration）时，还必须严格早于预留截止时刻——恰到截止时刻
// 及之后预留已按超时规则全额退回，任何结算（含实际费用为零）都不可能成功。
//
// 时间一律按保存的完整时刻以 time.Time 的绝对瞬间比较（Equal/Before）：
// 纳秒精度保留，截止前不足一秒的合法结算不会被当成超时；不同时区表示的同一
// 时刻判定相同。关闭预留超时（reserveDuration==0）时没有截止时刻，沿用原有
// 结算规则、不人为增加期限。该校验只针对备份记载的预留与结算时刻，与恢复时
// 的当前时间无关：期限内完成的结算在很久以后恢复仍是已结算。
func validateSettlementTiming(r *request) error {
	if r.settledAt.Before(r.reservedAt) {
		return fmt.Errorf("settled_at %v is before reserved_at %v", r.settledAt, r.reservedAt)
	}
	if r.reserveDuration > 0 && !r.settledAt.Before(r.reserveDeadline) {
		return fmt.Errorf("settled_at %v is not within the valid reserve window ending strictly before reserve deadline %v", r.settledAt, r.reserveDeadline)
	}
	return nil
}

// validateSubmissionTiming 校验请求记载的提交时刻必须是正常申请能够产生的
// 历史：正常提交时，策略尚未开始、已经结束或申请会话已经到期的申请都会被
// 拒绝（只留下不关联请求的拒绝账本记录），不可能进入已受理请求序列。因此
// 备份中每笔已受理请求的提交时刻必须：
//   - 不早于关联策略的开始时刻（恰在策略开始时提交可以接受）；
//   - 严格早于策略结束时刻（恰在策略结束时提交必须拒绝）；
//   - 严格早于申请会话的到期时刻（恰在会话到期时提交必须拒绝）。
//
// 直接预留与经过审批的申请适用同一规则；后来已经结算、取消、拒绝或过期
// （含预留超时）的请求也不豁免。时间一律按保存的完整时刻以 time.Time 的
// 绝对瞬间比较（Before）：纳秒精度保留，不同时区表示的同一时刻判定相同。
// 该校验只针对备份记载的提交历史，与恢复时的当前时间无关：申请当时符合
// 条件、之后会话到期或被吊销、策略结束或被停用的请求仍按现有规则恢复。
func validateSubmissionTiming(r *request, p *policy, sess *session) error {
	if r.createdAt.Before(p.startsAt) {
		return fmt.Errorf("created_at %v is before policy %q window starts_at %v", r.createdAt, p.id, p.startsAt)
	}
	if !r.createdAt.Before(p.endsAt) {
		return fmt.Errorf("created_at %v is not strictly before policy %q window ends_at %v", r.createdAt, p.id, p.endsAt)
	}
	if !r.createdAt.Before(sess.expiresAt) {
		return fmt.Errorf("created_at %v is not strictly before session %q expiry %v", r.createdAt, sess.id, sess.expiresAt)
	}
	return nil
}

// validateRequestTimingAndState 校验请求状态与其计时/金额字段自洽，并与
// 不可变的策略条件、申请会话保持一致，防止任意状态搭配任意时间戳的损坏
// 备份。sess 为该请求的申请会话。
func validateRequestTimingAndState(r *request, p *policy, sess *session) error {
	if r.createdAt.IsZero() {
		return errors.New("request missing created_at")
	}
	// 提交时刻必须是正常申请能够产生的历史：落在策略时间窗内且申请会话
	// 尚未到期。对直接预留与经过审批的申请、以及所有后续状态统一适用。
	if err := validateSubmissionTiming(r, p, sess); err != nil {
		return err
	}
	if r.operation == "" || r.payee == "" {
		return errors.New("operation and payee are required")
	}
	if r.operation != p.operation || r.payee != p.payee {
		return fmt.Errorf("operation/payee do not match policy %q", p.id)
	}
	if r.estimatedFee > p.maxPerRequest {
		return fmt.Errorf("estimated fee %d exceeds policy per-request limit %d", r.estimatedFee, p.maxPerRequest)
	}
	if r.approverAccountID != "" && r.approverAccountID != r.payerAccountID {
		return fmt.Errorf("approver account %q is not the payer %q", r.approverAccountID, r.payerAccountID)
	}
	if r.actualFee > r.estimatedFee {
		return fmt.Errorf("actual fee %d exceeds estimated fee %d", r.actualFee, r.estimatedFee)
	}

	// 申请是否必须走过审批由不可变策略门槛决定：费用严格超过正门槛的请求
	// 只能来自待审批流程；其余请求只能直接预留。
	approvalRequired := p.approvalThreshold > 0 && r.estimatedFee > p.approvalThreshold
	reservedOrigin := !r.reservedAt.IsZero()

	switch r.state {
	case RequestReserved, RequestSettled, RequestReservationExpired:
		// 这三类一定发生过预留。
		if err := validateReservedOrigin(r, p, sess, approvalRequired, reservedOrigin); err != nil {
			return err
		}
	case RequestPendingApproval, RequestRejected, RequestExpired:
		// 这三类一定从未预留，且必须来自开启审批的策略。
		if err := validatePendingOrigin(r, p, approvalRequired, reservedOrigin); err != nil {
			return err
		}
	case RequestCancelled:
		// 取消可能来自待审批（从未预留）或已预留。
		if reservedOrigin {
			if err := validateReservedOrigin(r, p, sess, approvalRequired, true); err != nil {
				return err
			}
		} else {
			if err := validatePendingOrigin(r, p, approvalRequired, false); err != nil {
				return err
			}
		}
	default:
		return fmt.Errorf("unknown state %d", r.state)
	}

	switch r.state {
	case RequestReserved:
		// 启用超时时 deadline 必须等于 reservedAt + 时长，未启用时为零，
		// 且不得已记录超时。
		if err := validateReserveTiming(r); err != nil {
			return err
		}
		if !r.reserveExpiredAt.IsZero() {
			return errors.New("reserved request must not carry reserve-expired time")
		}
		if r.actualFee != 0 || !r.settledAt.IsZero() {
			return errors.New("reserved request must not be settled")
		}
		if r.rejectReason != "" {
			return errors.New("reserved request must not carry a reject reason")
		}
	case RequestSettled:
		if r.settledAt.IsZero() {
			return errors.New("settled request missing settled_at")
		}
		if !r.reserveExpiredAt.IsZero() {
			return errors.New("settled request must not carry reserve-expired time")
		}
		if err := validateReserveTiming(r); err != nil {
			return err
		}
		// 结算时刻必须落在有效预留期内：启用预留超时时严格早于截止时刻。
		if err := validateSettlementTiming(r); err != nil {
			return err
		}
		if r.rejectReason != "" {
			return errors.New("settled request must not carry a reject reason")
		}
	case RequestCancelled:
		if r.actualFee != 0 || !r.settledAt.IsZero() {
			return errors.New("cancelled request must not be settled")
		}
		if !r.reserveExpiredAt.IsZero() {
			return errors.New("cancelled request must not carry reserve-expired time")
		}
		if r.rejectReason != "" {
			return errors.New("cancelled request must not carry a reject reason")
		}
		if reservedOrigin {
			if err := validateReserveTiming(r); err != nil {
				return err
			}
		} else {
			// 待审批取消：决定时间必填，且等待期限与取消决定时刻必须是
			// 正常取消能够产生的历史。
			if r.decidedAt.IsZero() {
				return errors.New("cancelled-from-pending request missing decided_at")
			}
			if err := validateWaitDeadline(r, p, sess, "cancelled-from-pending request"); err != nil {
				return err
			}
			if err := validateWaitDecisionTiming(r, "cancellation"); err != nil {
				return err
			}
		}
	case RequestPendingApproval:
		// 待审批不冻结余额：不得有实际费用，且等待期限必须等于
		// min(提交+等待时长, 策略结束, 申请会话到期)。
		if r.actualFee != 0 || !r.settledAt.IsZero() {
			return errors.New("pending request must not be settled")
		}
		if r.waitDeadline.IsZero() {
			return errors.New("pending request missing wait deadline")
		}
		if r.approverAccountID != "" {
			return errors.New("pending request must not carry an approver")
		}
		if r.rejectReason != "" {
			return errors.New("pending request must not carry a reject reason")
		}
		// 已停用策略下不得残留待审批请求：正常停用时，未到等待期限的待审批
		// 请求会立即随停用进入拒绝终态，已到（含恰到）或超过期限的进入过期
		// 终态，二者皆终态、不再等待批准。备份保存的“已停用策略 + 待审批
		// 请求”是正常流程不可能产生的矛盾状态，必须整体拒绝。该校验只看备份
		// 保存的状态，与恢复时的当前时间无关：等待期限尚未到达、恰好到达或
		// 早已过去结果相同；不能先在恢复时把该请求自动过期、再把矛盾备份当作
		// 合法数据，也不替调用方补写停用拒绝记录、清除停用标志或改写请求。
		// 停用前已进入其他状态（已预留、已结算、已取消、被拒绝、已过期、预留
		// 超时）的历史请求不受此限，已停用策略本身及其全部合法历史仍可恢复。
		if p.deactivated {
			return fmt.Errorf("usage account %q request %q is still pending approval under deactivated policy %q: a deactivated policy cannot retain pending-approval requests", r.accountID, r.requestID, p.id)
		}
		// 已吊销申请会话下不得残留待审批请求：主动吊销会话时，未到等待期限的
		// 待审批请求会立即随吊销进入拒绝终态，已到（含恰到）或超过期限的进入
		// 过期终态，二者皆终态、不再等待批准。备份保存的“申请会话已吊销 +
		// 待审批请求”是正常流程不可能产生的矛盾状态，必须整体拒绝。该校验只看
		// 备份保存的吊销标记与请求状态，与恢复时的当前时间无关：等待期限尚未
		// 到达、恰好到达或早已过去结果相同；不能先在恢复时把该请求按当前时间
		// 自动过期、再把矛盾备份当作合法数据，也不替调用方补写吊销拒绝决定、
		// 猜测吊销时间、清除吊销标记或删除请求来消除矛盾。这里按提交申请所用的
		// 会话判断：即使出资账户用于审批的会话仍然有效，也不能让矛盾备份恢复
		// 成功。吊销前已进入其他状态（已预留、已结算、已取消、被拒绝、已过期、
		// 预留超时）的历史请求不受此限，已吊销会话本身及其全部合法历史仍可恢复。
		if sess.revoked {
			return fmt.Errorf("usage account %q request %q is still pending approval under revoked application session %q: a revoked session cannot retain pending-approval requests", r.accountID, r.requestID, sess.id)
		}
		// 待审批没有决定时刻，只需核对保存的等待截止时刻。
		if err := validateWaitDeadline(r, p, sess, "pending request"); err != nil {
			return err
		}
	case RequestRejected:
		if r.decidedAt.IsZero() || r.rejectReason == "" {
			return errors.New("rejected request missing decided_at or reason")
		}
		// 等待截止时刻与拒绝决定时刻必须是正常审批流程能够产生的历史：
		// 出资账户主动拒绝、申请会话吊销、策略停用三条路径统一适用。
		if err := validateWaitDeadline(r, p, sess, "rejected request"); err != nil {
			return err
		}
		if err := validateWaitDecisionTiming(r, "rejection"); err != nil {
			return err
		}
	case RequestExpired:
		if r.decidedAt.IsZero() {
			return errors.New("expired request missing decided_at")
		}
		if r.rejectReason != "" {
			return errors.New("expired request must not carry a reject reason")
		}
		// 等待截止时刻与过期决定时刻必须是正常到期处理能够产生的历史：
		// 截止时刻必须等于提交时确定的期限，决定不得早于该截止时刻。
		if err := validateExpirationTiming(r, p, sess); err != nil {
			return err
		}
	case RequestReservationExpired:
		if r.reserveDuration <= 0 {
			return errors.New("reservation-expired request must have a positive reserve duration")
		}
		if err := validateReserveTiming(r); err != nil {
			return err
		}
		if !r.reserveExpiredAt.Equal(r.reserveDeadline) {
			return errors.New("reserve-expired-at must equal reserve deadline")
		}
		if r.actualFee != 0 || !r.settledAt.IsZero() {
			return errors.New("reservation-expired request must not be settled")
		}
		if r.rejectReason != "" {
			return errors.New("reservation-expired request must not carry a reject reason")
		}
	}
	return nil
}

// expectedWaitDeadline 计算审批路径请求的等待截止时刻：提交时刻 + 策略
// 等待时长、策略结束时间、申请会话到期时间三者中的最早值。所有走过审批
// 流程的请求（待审批、批准、拒绝、待审批取消、待审批过期）保存的等待
// 截止时刻都必须与该值一致。
func expectedWaitDeadline(r *request, p *policy, sess *session) time.Time {
	want := r.createdAt.Add(p.approvalWait)
	if p.endsAt.Before(want) {
		want = p.endsAt
	}
	if sess.expiresAt.Before(want) {
		want = sess.expiresAt
	}
	return want
}

// validateWaitDeadline 核对审批路径请求保存的等待截止时刻自洽：不得缺失，
// 且必须等于提交时刻+策略等待时长、策略结束时间、申请会话到期时间三者的
// 最早值；提前或推迟都拒绝，即使决定时刻仍落在修改后的期限内。
//
// whatNoun 为请求所处的审批环节名称（如 "approved request"、"rejected
// request"、"cancelled-from-pending request"、"expired request"），用于保留
// 各环节原有的错误措辞。待审批、批准、拒绝、待审批取消与待审批过期共用这
// 同一条业务规则，不再分别维护。
//
// 时间一律按保存的完整时刻以 time.Time 的绝对瞬间比较（Equal）：纳秒精度
// 保留，不同时区表示的同一时刻判定相同。该校验只针对备份记载的历史时刻，
// 与恢复时的当前时间无关。
func validateWaitDeadline(r *request, p *policy, sess *session, whatNoun string) error {
	if r.waitDeadline.IsZero() {
		return fmt.Errorf("%s missing wait deadline", whatNoun)
	}
	if want := expectedWaitDeadline(r, p, sess); !r.waitDeadline.Equal(want) {
		return fmt.Errorf("wait deadline %v does not match min(created+wait, policy end, session expiry) %v", r.waitDeadline, want)
	}
	return nil
}

// validateWaitDecisionTiming 核对“期限内决定”（批准、拒绝、待审批取消）
// 共用的决定时刻规则：决定必须不早于提交时刻（恰在提交时刻决定可以接受），
// 且严格早于等待截止时刻——决定早于提交、恰到截止时刻或晚于截止时刻都不
// 可能在正常审批流程中产生（截止时刻及之后请求只能进入待审批过期终态）。
//
// actionNoun 为操作名称（"approval"、"rejection"、"cancellation"），用于保留
// 各操作原有的错误措辞。调用方须先通过 validateWaitDeadline 确认截止时刻
// 存在且正确，本函数不再重复该核对。时间一律按保存的完整时刻以 time.Time
// 的绝对瞬间比较（Before）：纳秒精度保留，不同时区表示的同一时刻判定相同。
// 该校验只针对备份记载的提交与决定历史，与恢复时的当前时间无关：期限内的
// 合法决定即使很久以后恢复、申请会话已到期或吊销、策略已结束或停用，仍保持
// 原状态、金额、决定信息与账本顺序，不追加退款或过期记录。
func validateWaitDecisionTiming(r *request, actionNoun string) error {
	if r.decidedAt.Before(r.createdAt) {
		return fmt.Errorf("%s decided_at %v is before created_at %v", actionNoun, r.decidedAt, r.createdAt)
	}
	if !r.decidedAt.Before(r.waitDeadline) {
		return fmt.Errorf("%s decided_at %v is not strictly before wait deadline %v", actionNoun, r.decidedAt, r.waitDeadline)
	}
	return nil
}

// validateExpirationTiming 校验“待审批过期”（从未预留费用、因等待审批到期
// 进入已过期终态）的请求保存的等待期限与过期决定时刻自洽，防止备份中出现
// 正常流程不可能产生的过期历史：
//   - 等待截止时刻核对与批准、拒绝、待审批取消共用同一规则（见
//     validateWaitDeadline）：缺失、提前、推迟都拒绝，即使修改后的截止时刻
//     仍早于记载的过期决定；策略结束或会话到期更早时按最早的那个时刻判断，
//     不能只按最长等待时长；
//   - 过期决定时刻必须存在，且不早于等待截止时刻：恰到截止时刻发现过期可以
//     接受，早于它必须拒绝。钱包可能在到期很久之后才（因查询、新申请或导出）
//     发现请求过期，因此合法决定时刻可以远晚于截止时刻，恢复时不得把它改写
//     为截止时刻或当前时间。
//
// 时间一律按保存的完整时刻以 time.Time 的绝对瞬间比较（Equal/Before）：
// 纳秒精度保留，不同时区表示的同一时刻判定相同。该校验只针对备份记载的
// 申请与过期历史，与恢复时的当前时间无关：合法过期即使恢复时申请会话已
// 到期或被吊销、策略已结束或停用，仍保持原过期状态、提交时刻、等待截止
// 与决定时刻及既有账本顺序，不追加过期记录，不产生预留、扣减或退款。
// 已预留费用的预留超时（RequestReservationExpired）不适用本规则。
func validateExpirationTiming(r *request, p *policy, sess *session) error {
	if err := validateWaitDeadline(r, p, sess, "expired request"); err != nil {
		return err
	}
	if r.decidedAt.Before(r.waitDeadline) {
		return fmt.Errorf("expiration decided_at %v is before wait deadline %v", r.decidedAt, r.waitDeadline)
	}
	return nil
}

// validateReservedOrigin 校验“发生过预留”的请求：预留计时字段必须齐全、
// 预留时长快照必须与策略一致，且审批路径（批准人、决定时间、等待期限）与
// 费用/门槛相匹配。对所有发生过预留的状态（已预留、已结算、预留超时、
// 已预留后取消）统一适用：超门槛的必须经出资账户在等待期限内于预留时刻
// 批准；未超门槛（或策略关闭审批）的直接受理请求不得携带批准人或决定时间，
// 且实际预留时刻必须与提交时刻为同一瞬间——正常申请无需审批时，提交成功
// 即同时完成费用预留，预留起点不可能早于或晚于提交时刻。
func validateReservedOrigin(r *request, p *policy, sess *session, approvalRequired, reservedOrigin bool) error {
	if !reservedOrigin {
		return errors.New("request is in a reserved-origin state but missing reserved_at")
	}
	if r.reserveDuration != p.maxReserveDuration {
		return fmt.Errorf("reserve duration %v does not match policy max reserve duration %v", r.reserveDuration, p.maxReserveDuration)
	}
	if approvalRequired {
		if r.approverAccountID != r.payerAccountID {
			return errors.New("above-threshold request was reserved without payer approval")
		}
		if !r.decidedAt.Equal(r.reservedAt) {
			return errors.New("approved request decided_at must equal reserved_at")
		}
		// 等待截止时刻与批准时刻必须是正常审批流程能够产生的历史：即使该
		// 预留后来已经结算、取消或超时退回，也不放宽这一要求。
		if err := validateWaitDeadline(r, p, sess, "approved request"); err != nil {
			return err
		}
		if err := validateWaitDecisionTiming(r, "approval"); err != nil {
			return err
		}
	} else {
		if r.approverAccountID != "" {
			return errors.New("below-threshold request must not carry an approver")
		}
		if !r.decidedAt.IsZero() {
			return errors.New("directly reserved request must not carry decided_at")
		}
		// 直接受理的请求在提交成功的同一时刻完成费用预留：实际预留时刻必须
		// 与提交时刻是同一瞬间。预留起点提前或推迟均拒绝，即使只差一纳秒——
		// 否则被篡改的预留起点会带着与之“自洽”的预留截止一起，把本应从受理
		// 时刻起算的预留推迟释放。时间按保存的完整绝对时刻比较（Equal）：
		// 不同时区表示的同一时刻判定相同。关闭预留超时（时长为零）的请求同样
		// 适用。该核对只针对备份记载的提交与预留时刻，与恢复时的当前时间无关：
		// 即使被篡改的预留截止在恢复时已经过去，也必须拒绝，不能先按超时退款
		// 再接受矛盾历史。
		if !r.reservedAt.Equal(r.createdAt) {
			return fmt.Errorf("directly reserved request reserved_at %v does not match created_at %v", r.reservedAt, r.createdAt)
		}
	}
	return nil
}

// validatePendingOrigin 校验“从未预留”的待审批系请求：不得携带任何预留
// 计时字段，且策略必须开启审批、费用必须严格超过门槛。
func validatePendingOrigin(r *request, p *policy, approvalRequired, reservedOrigin bool) error {
	if reservedOrigin {
		return errors.New("request is in a pending-origin state but carries reserved_at")
	}
	if !approvalRequired {
		return errors.New("request is in an approval state although policy approval is not enabled for its fee")
	}
	if !r.reserveDeadline.IsZero() || !r.reserveExpiredAt.IsZero() || r.reserveDuration != 0 {
		return errors.New("pending-origin request must not carry reserve timing")
	}
	return nil
}

package wallet

import (
	"errors"
	"fmt"
	"sort"
	"strings"
	"sync"
	"time"
)

// Wallet 是进程内的智能钱包。
//
// 所有方法都可被多个 goroutine 并发调用；每一次申请、结算或取消都在
// 同一把锁内原子完成，因此余额与共享累计额度不会被超扣，同一请求也
// 只会产生一个终态。状态仅在当前 Wallet 实例的生命周期内保留。
type Wallet struct {
	mu sync.Mutex

	// now 可在同包测试中替换，默认使用 time.Now。
	now func() time.Time

	accounts map[string]*account
	sessions map[string]*session
	policies map[string]*policy
	// requests 以“使用账户编号 + 请求编号”为键，实现按使用账户的幂等。
	requests map[requestKey]*request
	ledger   []LedgerEntry
}

type account struct {
	id        string
	available int64
	reserved  int64
	createdAt time.Time
}

type session struct {
	id        string
	accountID string
	deviceID  string
	expiresAt time.Time
	revoked   bool
	createdAt time.Time
}

type policy struct {
	id                string
	payerAccountID    string
	allowedAccounts   map[string]struct{}
	operation         string
	payee             string
	startsAt          time.Time
	endsAt            time.Time
	maxPerRequest     int64
	maxTotal          int64
	approvalThreshold int64
	approvalWait      time.Duration
	// maxReserveDuration 为最长预留时长；零表示关闭预留超时。
	maxReserveDuration time.Duration
	reservedTotal      int64
	spentTotal         int64

	deactivated          bool
	deactivatedAt        time.Time
	deactivatorAccountID string
	deactivateReason     string
}

type request struct {
	policyID       string
	requestID      string
	accountID      string
	payerAccountID string
	sessionID      string
	operation      string
	payee          string
	estimatedFee   int64
	actualFee      int64
	state          RequestState
	createdAt      time.Time
	settledAt      time.Time
	waitDeadline   time.Time
	// reservedAt 为费用实际预留完成的时刻（直接受理或批准成功的时刻）。
	reservedAt time.Time
	// reserveDuration 为预留时适用的最长预留时长快照；零表示未启用超时。
	reserveDuration time.Duration
	// reserveDeadline 为预留截止时刻（reservedAt + reserveDuration）。
	reserveDeadline time.Time
	// reserveExpiredAt 为超时释放时间；惰性处理时记录的仍是截止时刻本身。
	reserveExpiredAt  time.Time
	decidedAt         time.Time
	approverAccountID string
	rejectReason      string
}

type requestKey struct {
	accountID string
	requestID string
}

// New 创建一个空钱包。
func New() *Wallet {
	return &Wallet{
		now:      time.Now,
		accounts: make(map[string]*account),
		sessions: make(map[string]*session),
		policies: make(map[string]*policy),
		requests: make(map[requestKey]*request),
	}
}

// CreateAccount 创建具有唯一编号和初始代付余额的账户。
//
// 金额为最小货币单位的整数；初始余额为负或编号重复时返回错误，
// 且不会改动任何已有资金记录。
func (w *Wallet) CreateAccount(id string, initialBalance int64) (AccountView, error) {
	if id == "" {
		return AccountView{}, ErrEmptyAccountID
	}
	if initialBalance < 0 {
		return AccountView{}, fmt.Errorf("%w: initial balance must not be negative", ErrInvalidAmount)
	}

	w.mu.Lock()
	defer w.mu.Unlock()

	if _, ok := w.accounts[id]; ok {
		return AccountView{}, fmt.Errorf("%w: %s", ErrAccountExists, id)
	}
	now := w.now()
	acc := &account{id: id, available: initialBalance, createdAt: now}
	w.accounts[id] = acc
	return acc.view(), nil
}

// Account 查询账户视图；账户不存在时返回 ErrAccountNotFound。
// 查询时已到期的预留会先被自动释放，因此视图反映最新的可用/预留余额。
func (w *Wallet) Account(id string) (AccountView, error) {
	w.mu.Lock()
	defer w.mu.Unlock()

	acc, ok := w.accounts[id]
	if !ok {
		return AccountView{}, fmt.Errorf("%w: %s", ErrAccountNotFound, id)
	}
	w.expireReservationsLocked(w.now())
	return acc.view(), nil
}

// Balance 查询账户的可用余额与预留余额。
func (w *Wallet) Balance(id string) (Balances, error) {
	view, err := w.Account(id)
	if err != nil {
		return Balances{}, err
	}
	return view.Balances, nil
}

// CreateSession 为账户创建一个绑定设备、带到期时间的会话。
//
// 会话编号全局唯一；账户必须存在。
func (w *Wallet) CreateSession(id, accountID, deviceID string, expiresAt time.Time) (SessionView, error) {
	if id == "" || accountID == "" || deviceID == "" {
		return SessionView{}, fmt.Errorf("%w: session id, account id and device id are required", ErrInvalidArgument)
	}

	w.mu.Lock()
	defer w.mu.Unlock()

	if _, ok := w.accounts[accountID]; !ok {
		return SessionView{}, fmt.Errorf("%w: %s", ErrAccountNotFound, accountID)
	}
	if _, ok := w.sessions[id]; ok {
		return SessionView{}, fmt.Errorf("%w: %s", ErrSessionExists, id)
	}
	now := w.now()
	sess := &session{
		id:        id,
		accountID: accountID,
		deviceID:  deviceID,
		expiresAt: expiresAt,
		createdAt: now,
	}
	w.sessions[id] = sess
	return sess.view(), nil
}

// RevokeSession 主动吊销会话。会话不存在返回 ErrSessionNotFound；已经到期
// 的会话也允许吊销；重复吊销视为成功且不重复留痕。吊销后不再受理该会话
// 的新申请。
//
// 吊销瞬间按各请求自身的等待截止时间分别结清该会话仍在待审批的请求：
// 当前时刻严格早于截止时间的进入拒绝终态并说明申请会话已被吊销，决定
// 时间为吊销时刻；当前时刻等于或晚于截止时间（等待时长耗尽、策略结束
// 或申请会话到期先发生）的进入过期终态，不带吊销拒绝原因、不填写审批
// 账户，提交时间与等待截止时间保持不变。终态结果只取决于申请自身的
// 期限，不因吊销前是否被查询过而不同；先前已进入终态的请求保留原决定
// 信息与历史记录。
//
// 两类处理都不冻结费用：不改变出资余额、策略预留总额和已花费总额，也不
// 生成退款、扣减或预留记录。已预留请求继续按原规则结算、取消或等待自身
// 预留超时，吊销不提前释放费用；其他会话的申请不受影响。
func (w *Wallet) RevokeSession(id string) error {
	w.mu.Lock()
	defer w.mu.Unlock()

	sess, ok := w.sessions[id]
	if !ok {
		return fmt.Errorf("%w: %s", ErrSessionNotFound, id)
	}
	if sess.revoked {
		return nil
	}
	sess.revoked = true
	now := w.now()
	reason := "application session revoked before approval"

	pending := make([]*request, 0)
	for _, req := range w.requests {
		if req.state == RequestPendingApproval && req.sessionID == sess.id {
			pending = append(pending, req)
		}
	}
	w.settlePendingLocked(pending, now, func(req *request) {
		// 未到等待期限：随会话吊销进入拒绝终态，不填写审批账户。
		req.state = RequestRejected
		req.rejectReason = reason
		req.decidedAt = now
		w.ledger = append(w.ledger, LedgerEntry{
			Kind:      LedgerRejection,
			AccountID: req.accountID,
			RequestID: req.requestID,
			Reason:    reason,
			At:        now,
		})
	})
	return nil
}

// Session 查询会话视图。
func (w *Wallet) Session(id string) (SessionView, error) {
	w.mu.Lock()
	defer w.mu.Unlock()

	sess, ok := w.sessions[id]
	if !ok {
		return SessionView{}, fmt.Errorf("%w: %s", ErrSessionNotFound, id)
	}
	return sess.view(), nil
}

// SavePolicy 保存（创建）一条代付策略。
//
// 出资账户和所有使用账户必须存在，限额必须为正，开始时间必须严格早于
// 结束时间，编号不得重复，否则拒绝保存并返回包装了具体原因的错误。
func (w *Wallet) SavePolicy(spec PolicySpec) error {
	if spec.ID == "" {
		return fmt.Errorf("%w: policy id is required", ErrPolicyInvalid)
	}
	// 策略自身的参数规则与备份恢复共用同一套判断（见
	// validatePolicySpecParams），这里只补充保存入口特有的编号与账户检查。
	if err := validatePolicySpecParams(spec); err != nil {
		return fmt.Errorf("%w: %v", ErrPolicyInvalid, err)
	}

	w.mu.Lock()
	defer w.mu.Unlock()

	if _, ok := w.policies[spec.ID]; ok {
		return fmt.Errorf("%w: %s", ErrPolicyExists, spec.ID)
	}
	if _, ok := w.accounts[spec.PayerAccountID]; !ok {
		return fmt.Errorf("%w: payer account %q: %w", ErrPolicyInvalid, spec.PayerAccountID, ErrAccountNotFound)
	}
	allowed := make(map[string]struct{}, len(spec.AllowedAccountIDs))
	for _, id := range spec.AllowedAccountIDs {
		if _, ok := w.accounts[id]; !ok {
			return fmt.Errorf("%w: allowed account %q: %w", ErrPolicyInvalid, id, ErrAccountNotFound)
		}
		allowed[id] = struct{}{}
	}

	w.policies[spec.ID] = &policy{
		id:                 spec.ID,
		payerAccountID:     spec.PayerAccountID,
		allowedAccounts:    allowed,
		operation:          spec.Operation,
		payee:              spec.Payee,
		startsAt:           spec.StartsAt,
		endsAt:             spec.EndsAt,
		maxPerRequest:      spec.MaxPerRequest,
		maxTotal:           spec.MaxTotal,
		approvalThreshold:  spec.ApprovalThreshold,
		approvalWait:       spec.ApprovalWait,
		maxReserveDuration: spec.MaxReserveDuration,
	}
	return nil
}

// validatePolicySpecParams 校验策略自身的参数规则，供 SavePolicy 与备份恢复
// 两个入口共用，避免同一套业务规则分别维护。只覆盖与钱包状态无关的参数
// 合法性：策略编号、编号重复、账户存在性、授权账户重复列出等由各入口按
// 各自口径另行判断（保存时重复授权账户按同一账户处理，备份则拒绝）。
//
// 规则与顺序固定为：必填内容 -> 正数限额 -> 审批配置 -> 最长预留时长 ->
// 时间窗先后 -> 出资与授权账户必填。其中审批门槛与等待时长联动：门槛为零
// 表示关闭审批，此时等待时长不被使用，任意取值（含负值）都合法并原样
// 保留；门槛为正时等待时长必须为正，且门槛不得超过单次上限（恰好等于
// 单次上限合法）。最长预留时长是独立设置：零表示关闭预留超时，负值始终
// 无效，不因审批关闭而忽略。时间窗只要求开始严格早于结束，不要求策略在
// 当前时刻有效（尚未开始或已经结束但窗口本身合法的策略均可通过）。
//
// 返回的错误只携带具体原因文本，包装成各入口对外的错误类别
// （ErrPolicyInvalid / ErrBackupInvalid）由调用方负责。
func validatePolicySpecParams(spec PolicySpec) error {
	if spec.Operation == "" || spec.Payee == "" {
		return errors.New("operation and payee are required")
	}
	if spec.MaxPerRequest <= 0 || spec.MaxTotal <= 0 {
		return errors.New("limits must be positive")
	}
	// 审批门槛：零表示关闭；不得为负，不得超过单次上限；开启时等待时长必须为正。
	if spec.ApprovalThreshold < 0 {
		return errors.New("approval threshold must not be negative")
	}
	if spec.ApprovalThreshold > 0 {
		if spec.ApprovalThreshold > spec.MaxPerRequest {
			return fmt.Errorf("approval threshold %d exceeds per-request limit %d", spec.ApprovalThreshold, spec.MaxPerRequest)
		}
		if spec.ApprovalWait <= 0 {
			return errors.New("approval wait must be positive when approval is enabled")
		}
	}
	// 最长预留时长：零表示关闭预留超时（保持既有行为）；不得为负。
	if spec.MaxReserveDuration < 0 {
		return errors.New("max reserve duration must not be negative")
	}
	if !spec.StartsAt.Before(spec.EndsAt) {
		return errors.New("starts-at must be before ends-at")
	}
	if spec.PayerAccountID == "" || len(spec.AllowedAccountIDs) == 0 {
		return errors.New("payer account and at least one allowed account are required")
	}
	return nil
}

// Policy 查询策略视图，含当前预留中与已结算的累计金额。查询时已到期的
// 预留会先被自动释放，ReservedTotal 因而反映释放后的结果。
func (w *Wallet) Policy(id string) (PolicyView, error) {
	w.mu.Lock()
	defer w.mu.Unlock()

	p, ok := w.policies[id]
	if !ok {
		return PolicyView{}, fmt.Errorf("%w: %s", ErrPolicyNotFound, id)
	}
	w.expireReservationsLocked(w.now())
	return p.view(), nil
}

// DeactivatePolicy 由出资账户主动停用一条代付策略，立即停止该策略继续
// 受理代付。停用不可撤销。
//
// 必须使用该策略出资账户绑定当前设备的有效会话：会话不存在、不属于出资
// 账户、设备不符、已吊销或已到期时返回 ErrNotPolicyOwner，不改变策略、
// 请求或账本。策略编号、会话编号、设备缺失，或理由去掉首尾空白后为空，
// 返回 ErrInvalidArgument。策略不存在返回 ErrPolicyNotFound。保存与比较
// 理由均使用去掉首尾空白后的内容。
//
// 再次停用仍须通过会话校验：理由与首次相同时幂等返回首次结果，理由不同
// 返回 ErrConflict；两者都不改写首次停用信息，也不增加账本记录。尚未
// 开始或已经结束的策略也允许停用；停用后该编号不能再保存成新策略。
//
// 停用成功时，该策略下未到等待期限的待审批请求立即转为拒绝终态，拒绝
// 信息说明策略被停用并包含停用理由，决定时间为停用时间；已到（含恰到）
// 或超过等待期限的待审批请求进入过期终态。两类处理都不冻结余额、不占用
// 额度，也不产生退款；其他状态的请求与其他策略不受影响。
func (w *Wallet) DeactivatePolicy(policyID, sessionID, deviceID, reason string) (PolicyView, error) {
	reason = strings.TrimSpace(reason)
	if policyID == "" || sessionID == "" || deviceID == "" || reason == "" {
		return PolicyView{}, fmt.Errorf("%w: policy id, session id, device id and reason are required", ErrInvalidArgument)
	}

	w.mu.Lock()
	defer w.mu.Unlock()

	p, ok := w.policies[policyID]
	if !ok {
		return PolicyView{}, fmt.Errorf("%w: %s", ErrPolicyNotFound, policyID)
	}
	now := w.now()
	if err := w.checkPolicyOwnerLocked(p, sessionID, deviceID, now); err != nil {
		return PolicyView{}, err
	}
	// 鉴权通过后先释放已到期预留（停用不缩短任何未到期请求的截止时间）。
	w.expireReservationsLocked(now)

	if p.deactivated {
		// 停用不可撤销：理由相同返回首次结果，理由不同返回冲突，
		// 均不改写首次信息、不增加账本记录。
		if p.deactivateReason == reason {
			return p.view(), nil
		}
		return PolicyView{}, fmt.Errorf("%w: policy %s was already deactivated with a different reason", ErrConflict, policyID)
	}

	p.deactivated = true
	p.deactivatedAt = now
	p.deactivatorAccountID = p.payerAccountID
	p.deactivateReason = reason

	w.ledger = append(w.ledger, LedgerEntry{
		Kind:      LedgerPolicyDeactivation,
		AccountID: p.payerAccountID,
		PolicyID:  p.id,
		Reason:    reason,
		At:        now,
	})

	// 停用瞬间结清该策略全部待审批请求：未到等待期限的随停用立即拒绝，
	// 已到或超过期限的进入过期终态（不能因未被查询过而变成停用拒绝）。
	pending := make([]*request, 0)
	for _, req := range w.requests {
		if req.policyID == p.id && req.state == RequestPendingApproval {
			pending = append(pending, req)
		}
	}
	w.settlePendingLocked(pending, now, func(req *request) {
		msg := fmt.Sprintf("policy %s deactivated by payer: %s", p.id, reason)
		req.state = RequestRejected
		req.rejectReason = msg
		req.decidedAt = now
		req.approverAccountID = p.payerAccountID
		w.ledger = append(w.ledger, LedgerEntry{
			Kind:      LedgerRejection,
			AccountID: req.accountID,
			RequestID: req.requestID,
			Reason:    msg,
			At:        now,
		})
	})
	return p.view(), nil
}

// checkPolicyOwnerLocked 在持锁状态下校验停用会话：必须存在、归属策略的
// 出资账户、绑定当前设备、未吊销且未到期。任一不满足都返回
// ErrNotPolicyOwner，且不改变策略、请求或账本。
func (w *Wallet) checkPolicyOwnerLocked(p *policy, sessionID, deviceID string, now time.Time) error {
	sess, fail := w.checkSessionLocked(sessionID, p.payerAccountID, deviceID, now)
	if fail != sessionCheckOK {
		return authorizedSessionError(ErrNotPolicyOwner, sessionID, p.payerAccountID, deviceID, sess, fail)
	}
	return nil
}

// Apply 提交一笔代付申请。
//
// 校验顺序为：申请字段 -> 使用账户 -> 会话（存在性、归属、设备、吊销、
// 到期）-> 幂等请求编号 -> 策略授权与额度 -> 出资账户余额。任一环节
// 失败都会在账本中留下带具体原因的拒绝记录，不产生任何扣款或预留。
//
// 同一使用账户以相同请求编号重复申请：策略、操作类型、收款方和预估
// 费用一致时直接返回已有请求（不再预留）；任一不同则返回 ErrConflict。
func (w *Wallet) Apply(in RequestInput) (RequestView, error) {
	if in.EstimatedFee <= 0 {
		return RequestView{}, w.reject(in, fmt.Errorf("%w: estimated fee must be positive", ErrInvalidAmount))
	}
	if in.AccountID == "" || in.SessionID == "" || in.DeviceID == "" || in.RequestID == "" || in.PolicyID == "" {
		return RequestView{}, w.reject(in, fmt.Errorf("%w: account, session, device, policy and request id are required", ErrInvalidArgument))
	}

	w.mu.Lock()
	defer w.mu.Unlock()

	now := w.now()

	acc, ok := w.accounts[in.AccountID]
	if !ok {
		return RequestView{}, w.rejectLocked(in, now, fmt.Errorf("%w: %s", ErrAccountNotFound, in.AccountID))
	}
	_ = acc

	sess, fail := w.checkSessionLocked(in.SessionID, in.AccountID, in.DeviceID, now)
	if fail != sessionCheckOK {
		return RequestView{}, w.rejectLocked(in, now, applySessionError(in, sess, fail))
	}

	key := requestKey{accountID: in.AccountID, requestID: in.RequestID}
	if existing, ok := w.requests[key]; ok {
		// 待审批到期即过期、已预留到期即自动退回，重复申请看到的应是最新终态。
		w.refreshPendingLocked(existing, now)
		w.refreshReservedLocked(existing, now)
		if existing.policyID == in.PolicyID &&
			existing.operation == in.Operation &&
			existing.payee == in.Payee &&
			existing.estimatedFee == in.EstimatedFee {
			// 幂等命中：直接返回已有结果，不再预留、不记账。
			return existing.view(), nil
		}
		return RequestView{}, fmt.Errorf("%w: account %s request %s was already submitted with different content", ErrConflict, in.AccountID, in.RequestID)
	}

	p, ok := w.policies[in.PolicyID]
	if !ok {
		return RequestView{}, w.rejectLocked(in, now, fmt.Errorf("%w: %s", ErrPolicyNotFound, in.PolicyID))
	}
	// 停用后的策略不再受理新申请；历史请求的幂等查询在上方已先行处理。
	if p.deactivated {
		return RequestView{}, w.rejectLocked(in, now, fmt.Errorf("%w: policy %s deactivated: %s", ErrPolicyDeactivated, p.id, p.deactivateReason))
	}
	if _, ok := p.allowedAccounts[in.AccountID]; !ok {
		return RequestView{}, w.rejectLocked(in, now, fmt.Errorf("%w: account %s is not allowed by policy %s", ErrPolicyDenied, in.AccountID, p.id))
	}
	if in.Operation != p.operation {
		return RequestView{}, w.rejectLocked(in, now, fmt.Errorf("%w: operation %q does not match policy %q", ErrPolicyDenied, in.Operation, p.operation))
	}
	if in.Payee != p.payee {
		return RequestView{}, w.rejectLocked(in, now, fmt.Errorf("%w: payee %q does not match policy %q", ErrPolicyDenied, in.Payee, p.payee))
	}
	// 时间窗含开始、不含结束：[StartsAt, EndsAt)。
	if now.Before(p.startsAt) || !now.Before(p.endsAt) {
		return RequestView{}, w.rejectLocked(in, now, fmt.Errorf("%w: current time %s is outside policy window [%s, %s)", ErrPolicyDenied,
			now.Format(time.RFC3339), p.startsAt.Format(time.RFC3339), p.endsAt.Format(time.RFC3339)))
	}
	if in.EstimatedFee > p.maxPerRequest {
		return RequestView{}, w.rejectLocked(in, now, fmt.Errorf("%w: estimated fee %d exceeds per-request limit %d", ErrQuotaExceeded, in.EstimatedFee, p.maxPerRequest))
	}
	// 资金与额度检查前释放所有已到期预留（含同一出资账户在其他策略下的
	// 预留），因此先查余额还是先申请看到的可用金额都一致。
	w.expireReservationsLocked(now)
	// 预留中的费用同样占用共享累计额度。
	if used, exceed := quotaWouldExceedLocked(p, in.EstimatedFee); exceed {
		return RequestView{}, w.rejectLocked(in, now, fmt.Errorf("%w: estimated fee %d would exceed shared total limit %d (used %d)",
			ErrQuotaExceeded, in.EstimatedFee, p.maxTotal, used))
	}

	payer, ok := w.accounts[p.payerAccountID]
	if !ok {
		// 保存策略时已校验，这里仅作防御。
		return RequestView{}, w.rejectLocked(in, now, fmt.Errorf("payer account %s: %w", p.payerAccountID, ErrAccountNotFound))
	}
	if payer.available < in.EstimatedFee {
		return RequestView{}, w.rejectLocked(in, now, fmt.Errorf("%w: payer %s available %d, need %d", ErrInsufficientBalance, payer.id, payer.available, in.EstimatedFee))
	}

	// 所有硬性检查通过：预估费用严格超过审批门槛的进入待审批，其余直接预留。
	if p.approvalThreshold > 0 && in.EstimatedFee > p.approvalThreshold {
		// 待审批不冻结余额、不占用共享累计额度。期限取提交时刻 + 等待时长、
		// 策略结束时间、申请会话到期时间三者中的最早值。
		deadline := now.Add(p.approvalWait)
		if p.endsAt.Before(deadline) {
			deadline = p.endsAt
		}
		if sess.expiresAt.Before(deadline) {
			deadline = sess.expiresAt
		}
		req := &request{
			policyID:       p.id,
			requestID:      in.RequestID,
			accountID:      in.AccountID,
			payerAccountID: payer.id,
			sessionID:      sess.id,
			operation:      in.Operation,
			payee:          in.Payee,
			estimatedFee:   in.EstimatedFee,
			state:          RequestPendingApproval,
			createdAt:      now,
			waitDeadline:   deadline,
		}
		w.requests[key] = req
		w.ledger = append(w.ledger, LedgerEntry{
			Kind:      LedgerPendingApproval,
			AccountID: in.AccountID,
			RequestID: in.RequestID,
			Reason:    "pending approval for large amount",
			At:        now,
		})
		return req.view(), nil
	}

	// 所有硬性检查通过且无需审批：直接受理。以提交时刻作为实际预留时刻，
	// 不填写任何审批决定信息。
	req := &request{
		policyID:       p.id,
		requestID:      in.RequestID,
		accountID:      in.AccountID,
		payerAccountID: payer.id,
		sessionID:      sess.id,
		operation:      in.Operation,
		payee:          in.Payee,
		estimatedFee:   in.EstimatedFee,
		createdAt:      now,
	}
	w.reserveFeeLocked(p, payer, req, now, "reserve estimated fee")
	w.requests[key] = req
	return req.view(), nil
}

// Settle 结算一笔已预留的代付请求。
//
// actualFee 允许为零但不得为负、不得超过预留的预估费用。结算时扣除
// 实际费用并把差额退回可用余额。以相同实际费用重复结算幂等返回，不
// 重复记账；不同实际费用返回 ErrConflict。已取消的请求不能结算。
func (w *Wallet) Settle(accountID, requestID string, actualFee int64) (RequestView, error) {
	if actualFee < 0 {
		return RequestView{}, fmt.Errorf("%w: actual fee must not be negative", ErrInvalidAmount)
	}
	w.mu.Lock()
	defer w.mu.Unlock()

	req, p, err := w.lookupRequest(accountID, requestID)
	if err != nil {
		return RequestView{}, err
	}
	now := w.now()
	w.refreshPendingLocked(req, now)
	// 已到最长预留时长的预留先自动退回：此后任何结算都不能再扣款。
	w.refreshReservedLocked(req, now)
	switch req.state {
	case RequestSettled:
		if req.actualFee == actualFee {
			return req.view(), nil
		}
		return RequestView{}, fmt.Errorf("%w: request %s already settled with actual fee %d", ErrConflict, requestID, req.actualFee)
	case RequestCancelled:
		return RequestView{}, fmt.Errorf("%w: request %s", ErrAlreadyCancelled, requestID)
	case RequestReservationExpired:
		// 预留已超时全额退回：传入非负实际费用也返回明确的超时错误，不能扣款。
		return RequestView{}, fmt.Errorf("%w: request %s reservation expired at %s", ErrReservationExpired, requestID, req.reserveExpiredAt.Format(time.RFC3339))
	case RequestPendingApproval, RequestRejected, RequestExpired:
		// 结算只允许处理已预留请求。
		return RequestView{}, fmt.Errorf("%w: request %s is %v, only reserved requests can be settled", ErrRequestNotReserved, requestID, req.state)
	}

	if actualFee > req.estimatedFee {
		// 拒绝并保留预留。
		return RequestView{}, fmt.Errorf("%w: actual %d > estimated %d for request %s", ErrSettleTooLarge, actualFee, req.estimatedFee, requestID)
	}

	payer := w.accounts[req.payerAccountID]
	refund := req.estimatedFee - actualFee

	// 统一释放预留：出资账户预留余额与策略预留总额都按预估全额减少，实际
	// 费用计入策略已花费总额，差额退回该出资账户可用余额；实际费用等于预估
	// 时差额为零，只扣实际费用、不产生退款。
	w.releaseReservationLocked(p, payer, req, refund, actualFee)

	req.state = RequestSettled
	req.actualFee = actualFee
	req.settledAt = now

	w.ledger = append(w.ledger, LedgerEntry{
		Kind:      LedgerSettle,
		AccountID: payer.id,
		RequestID: requestID,
		Amount:    actualFee,
		Reason:    "settle actual fee",
		At:        now,
	})
	if refund > 0 {
		w.ledger = append(w.ledger, LedgerEntry{
			Kind:      LedgerRefund,
			AccountID: payer.id,
			RequestID: requestID,
			Amount:    refund,
			Reason:    "refund estimated-minus-actual fee",
			At:        now,
		})
	}
	return req.view(), nil
}

// Cancel 取消一笔尚未结算的代付请求。
//
// 待审批请求取消后直接进入取消终态，不产生退款（本就没有冻结余额）；
// 已预留请求取消后全部预留退回。已结算的请求不能取消；重复取消幂等
// 返回，不重复记账。已拒绝或已过期的请求不能取消。
func (w *Wallet) Cancel(accountID, requestID string) (RequestView, error) {
	w.mu.Lock()
	defer w.mu.Unlock()

	req, p, err := w.lookupRequest(accountID, requestID)
	if err != nil {
		return RequestView{}, err
	}
	now := w.now()
	w.refreshPendingLocked(req, now)
	// 已到最长预留时长的预留先自动退回。
	w.refreshReservedLocked(req, now)
	switch req.state {
	case RequestCancelled:
		return req.view(), nil
	case RequestSettled:
		return RequestView{}, fmt.Errorf("%w: request %s", ErrAlreadySettled, requestID)
	case RequestReservationExpired:
		// 预留已超时自动全额退回：取消幂等返回已有超时结果，不重复退回、不留痕。
		return req.view(), nil
	case RequestPendingApproval:
		// 待审批取消：无资金冻结，直接留取消终态。
		req.state = RequestCancelled
		req.decidedAt = now
		w.ledger = append(w.ledger, LedgerEntry{
			Kind:      LedgerCancellation,
			AccountID: req.accountID,
			RequestID: req.requestID,
			Reason:    "cancel pending-approval request",
			At:        now,
		})
		return req.view(), nil
	case RequestRejected, RequestExpired:
		return RequestView{}, fmt.Errorf("%w: request %s is %v, cannot cancel", ErrRequestNotReserved, requestID, req.state)
	}

	// 已预留：取消不产生实际费用，预估费用全额退回出资账户可用余额。
	payer := w.accounts[req.payerAccountID]
	w.releaseReservationLocked(p, payer, req, req.estimatedFee, 0)

	req.state = RequestCancelled

	w.ledger = append(w.ledger, LedgerEntry{
		Kind:      LedgerRefund,
		AccountID: payer.id,
		RequestID: requestID,
		Amount:    req.estimatedFee,
		Reason:    "refund reserved fee on cancel",
		At:        now,
	})
	return req.view(), nil
}

// Approve 批准一笔待审批的大额代付请求。
//
// 审批必须使用该策略出资账户绑定当前设备的有效会话；其他账户或无效
// 会话返回 ErrNotApprover 无权审批，且不改变请求。批准时再次检查出资
// 余额与共享剩余额度，足够才一次性预留全部预估费用并转为已预留；不足
// 时返回具体原因，保留待审批状态，期限内可再次批准。
//
// 已批准并处于预留或结算状态的请求重复批准只返回当前结果，不重复预留；
// 已拒绝、过期或取消的请求不能批准。截止时刻及之后不能批准。
func (w *Wallet) Approve(accountID, requestID, sessionID, deviceID string) (RequestView, error) {
	if accountID == "" || requestID == "" || sessionID == "" || deviceID == "" {
		return RequestView{}, fmt.Errorf("%w: account, request, session and device ids are required", ErrInvalidArgument)
	}
	w.mu.Lock()
	defer w.mu.Unlock()

	now := w.now()
	req, p, err := w.lookupRequest(accountID, requestID)
	if err != nil {
		return RequestView{}, err
	}
	if err := w.checkApproverLocked(req, sessionID, deviceID, now); err != nil {
		return RequestView{}, err
	}
	// 鉴权通过后释放已到期预留（含同一出资账户在其他策略下的预留），使
	// 批准的余额与额度检查计入退回；因余额或额度不足而失败的批准不会开始
	// 预留计时。
	w.expireReservationsLocked(now)
	w.refreshPendingLocked(req, now)
	if req.state == RequestExpired {
		return RequestView{}, fmt.Errorf("%w: approval deadline %s passed", ErrApprovalExpired, req.waitDeadline.Format(time.RFC3339))
	}

	switch req.state {
	case RequestPendingApproval:
		payer := w.accounts[req.payerAccountID]
		if payer.available < req.estimatedFee {
			return RequestView{}, fmt.Errorf("%w: payer %s available %d, need %d", ErrInsufficientBalance, payer.id, payer.available, req.estimatedFee)
		}
		if used, exceed := quotaWouldExceedLocked(p, req.estimatedFee); exceed {
			return RequestView{}, fmt.Errorf("%w: estimated fee %d would exceed shared total limit %d (used %d)",
				ErrQuotaExceeded, req.estimatedFee, p.maxTotal, used)
		}
		// 一次性完成全部预估费用的预留（资金划转、转已预留、预留记录与从批准
		// 成功时刻起算的预留计时）；余额或额度不足时已在上方返回，不会走到
		// 这里，因此失败的批准不会开始计时。
		w.reserveFeeLocked(p, payer, req, now, "reserve estimated fee on approval")
		// 批准成功保留原提交时刻与等待截止时刻；决定时间为批准时刻，并记录
		// 出资账户的批准决定。随后追加使用账户的零金额批准状态记录。
		req.decidedAt = now
		req.approverAccountID = payer.id
		w.ledger = append(w.ledger, LedgerEntry{
			Kind:      LedgerApproval,
			AccountID: req.accountID,
			RequestID: req.requestID,
			Reason:    "approve large-amount request",
			At:        now,
		})
		return req.view(), nil
	case RequestReserved, RequestSettled:
		// 已批准：重复批准幂等返回，不重复预留。
		return req.view(), nil
	default:
		return RequestView{}, fmt.Errorf("%w: request %s is %v, cannot approve", ErrRequestNotPending, requestID, req.state)
	}
}

// Reject 拒绝一笔待审批的大额代付请求。
//
// 拒绝必须使用该策略出资账户绑定当前设备的有效会话；其他账户或无效
// 会话返回 ErrNotApprover 无权审批，且不改变请求。拒绝理由为空或全为
// 空白时返回 ErrInvalidArgument 参数错误，请求保持不变。
//
// 重复拒绝且理由一致时幂等返回，不重复留痕；理由不同返回 ErrConflict。
// 已批准（含预留、结算）、已过期或已取消的请求不能拒绝。
func (w *Wallet) Reject(accountID, requestID, sessionID, deviceID, reason string) (RequestView, error) {
	if strings.TrimSpace(reason) == "" {
		return RequestView{}, fmt.Errorf("%w: reject reason must not be empty or blank", ErrInvalidArgument)
	}
	if accountID == "" || requestID == "" || sessionID == "" || deviceID == "" {
		return RequestView{}, fmt.Errorf("%w: account, request, session and device ids are required", ErrInvalidArgument)
	}
	w.mu.Lock()
	defer w.mu.Unlock()

	now := w.now()
	req, _, err := w.lookupRequest(accountID, requestID)
	if err != nil {
		return RequestView{}, err
	}
	if err := w.checkApproverLocked(req, sessionID, deviceID, now); err != nil {
		return RequestView{}, err
	}
	w.refreshPendingLocked(req, now)

	switch req.state {
	case RequestPendingApproval:
		req.state = RequestRejected
		req.rejectReason = reason
		req.decidedAt = now
		req.approverAccountID = req.payerAccountID

		w.ledger = append(w.ledger, LedgerEntry{
			Kind:      LedgerRejection,
			AccountID: req.accountID,
			RequestID: req.requestID,
			Reason:    reason,
			At:        now,
		})
		return req.view(), nil
	case RequestRejected:
		if req.rejectReason == reason {
			return req.view(), nil
		}
		return RequestView{}, fmt.Errorf("%w: request %s already rejected with a different reason", ErrConflict, requestID)
	default:
		return RequestView{}, fmt.Errorf("%w: request %s is %v, cannot reject", ErrRequestNotPending, requestID, req.state)
	}
}

// checkApproverLocked 在持锁状态下校验审批会话：必须存在、归属出资账户、
// 绑定当前设备、未吊销且未过期。任一不满足都返回 ErrNotApprover，且不
// 改变请求。
func (w *Wallet) checkApproverLocked(req *request, sessionID, deviceID string, now time.Time) error {
	sess, fail := w.checkSessionLocked(sessionID, req.payerAccountID, deviceID, now)
	if fail != sessionCheckOK {
		return authorizedSessionError(ErrNotApprover, sessionID, req.payerAccountID, deviceID, sess, fail)
	}
	return nil
}

// sessionCheckFailure 描述会话有效性校验未通过的具体条件，供提交申请、
// 出资账户审批与策略停用三个入口共用同一套判定，再各自翻译成对外错误：
// 申请区分为五类公开错误，审批与停用统一为无权错误但保留具体说明。
type sessionCheckFailure int

const (
	sessionCheckOK sessionCheckFailure = iota
	// sessionCheckMissing 会话不存在。
	sessionCheckMissing
	// sessionCheckAccount 会话存在但不属于要求的账户（申请时为使用账户，
	// 审批与停用时为出资账户）。
	sessionCheckAccount
	// sessionCheckDevice 会话归属账户正确，但绑定设备与提交设备不符。
	sessionCheckDevice
	// sessionCheckRevoked 会话已被吊销；与到期同时成立时优先报告吊销。
	sessionCheckRevoked
	// sessionCheckExpired 会话已到期；到期时刻本身即无效（[零值, ExpiresAt)
	// 才有效）。
	sessionCheckExpired
)

// checkSessionLocked 在持锁状态下按固定顺序校验会话：存在性、账户归属、
// 设备绑定、吊销、到期。校验只代表身份通过，不涉及任何策略、余额、额度
// 或请求状态判断。返回的 failure 为 sessionCheckOK 时 sess 即有效会话；
// 否则 sess 可能为 nil（会话不存在）或为找到的会话（用于错误说明），
// 本函数不改变任何状态。必须在持锁状态下调用。
func (w *Wallet) checkSessionLocked(sessionID, wantAccountID, deviceID string, now time.Time) (sess *session, failure sessionCheckFailure) {
	sess, ok := w.sessions[sessionID]
	if !ok {
		return nil, sessionCheckMissing
	}
	if sess.accountID != wantAccountID {
		return sess, sessionCheckAccount
	}
	// 设备仍按提交值与绑定值比较，不能因账户正确就跳过。
	if sess.deviceID != deviceID {
		return sess, sessionCheckDevice
	}
	if sess.revoked {
		return sess, sessionCheckRevoked
	}
	if !now.Before(sess.expiresAt) {
		return sess, sessionCheckExpired
	}
	return sess, sessionCheckOK
}

// applySessionError 把申请路径的会话校验失败翻译成对应的公开错误，错误
// 类别与说明沿用申请入口原有口径（不存在、账户不符、设备不符、吊销、
// 到期）。会话不存在时以提交的会话编号说明，其余以找到的会话说明。
func applySessionError(in RequestInput, sess *session, failure sessionCheckFailure) error {
	switch failure {
	case sessionCheckMissing:
		return fmt.Errorf("%w: %s", ErrSessionNotFound, in.SessionID)
	case sessionCheckAccount:
		return fmt.Errorf("%w: session %s belongs to account %s", ErrSessionAccountMismatch, sess.id, sess.accountID)
	case sessionCheckDevice:
		return fmt.Errorf("%w: session %s is bound to device %s", ErrSessionDeviceMismatch, sess.id, sess.deviceID)
	case sessionCheckRevoked:
		return fmt.Errorf("%w: session %s", ErrSessionRevoked, sess.id)
	case sessionCheckExpired:
		return fmt.Errorf("%w: session %s expired at %s", ErrSessionExpired, sess.id, sess.expiresAt.Format(time.RFC3339))
	default:
		return nil
	}
}

// authorizedSessionError 把审批与停用路径的会话校验失败统一包装成出资账户
// 无权错误（ErrNotApprover 或 ErrNotPolicyOwner），说明中保留导致失败的
// 具体会话条件，调用方仍可按无权错误类别识别。会话不存在时以提交的会话
// 编号说明，其余以找到的会话说明。
func authorizedSessionError(authErr error, sessionID, wantAccountID, deviceID string, sess *session, failure sessionCheckFailure) error {
	switch failure {
	case sessionCheckMissing:
		return fmt.Errorf("%w: session %s", authErr, sessionID)
	case sessionCheckAccount:
		return fmt.Errorf("%w: session %s belongs to account %s, not payer %s", authErr, sess.id, sess.accountID, wantAccountID)
	case sessionCheckDevice:
		return fmt.Errorf("%w: session %s is bound to device %s, not %s", authErr, sess.id, sess.deviceID, deviceID)
	case sessionCheckRevoked:
		return fmt.Errorf("%w: session %s revoked", authErr, sess.id)
	case sessionCheckExpired:
		return fmt.Errorf("%w: session %s expired at %s", authErr, sess.id, sess.expiresAt.Format(time.RFC3339))
	default:
		return nil
	}
}

// refreshPendingLocked 在持锁状态下检查待审批请求是否已到期限；到期
// （含到期时刻）则转为过期终态并记账。必须在持锁状态下调用。
func (w *Wallet) refreshPendingLocked(req *request, now time.Time) {
	if req.state != RequestPendingApproval {
		return
	}
	if now.Before(req.waitDeadline) {
		return
	}
	w.expirePendingLocked(req, now)
}

// expirePendingLocked 将一笔待审批请求转为过期终态：决定时间记录本次处理
// 时刻，拒绝理由与审批账户保持为空，账本只追加一条关联使用账户与请求编号
// 的零金额过期记录。不冻结或退回费用，不改变任何余额与额度。必须在持锁
// 状态下调用。
func (w *Wallet) expirePendingLocked(req *request, now time.Time) {
	req.state = RequestExpired
	req.decidedAt = now
	w.ledger = append(w.ledger, LedgerEntry{
		Kind:      LedgerExpiration,
		AccountID: req.accountID,
		RequestID: req.requestID,
		Reason:    "approval period expired",
		At:        now,
	})
}

// settlePendingLocked 按等待截止时刻顺序（同截止时刻按使用账户、请求编号
// 排序）分别结清 reqs 中仍在待审批的请求，保证账本追加顺序确定。每笔请求
// 只按自己的等待截止时间判断：now 严格早于截止时间且 reject 非空时调用
// reject 进入拒绝终态（拒绝理由与审批账户由调用方决定），恰到或超过截止
// 时间的进入过期终态；已到期的与仍在等待的请求互不影响，不因共用会话或
// 策略而混同。两类处理都不冻结费用、不改变余额与额度。必须在持锁状态下
// 调用。
func (w *Wallet) settlePendingLocked(reqs []*request, now time.Time, reject func(req *request)) {
	sortRequestsByDeadline(reqs, func(req *request) time.Time { return req.waitDeadline })
	for _, req := range reqs {
		if req.state != RequestPendingApproval {
			continue
		}
		if now.Before(req.waitDeadline) {
			if reject != nil {
				reject(req)
			}
			continue
		}
		w.expirePendingLocked(req, now)
	}
}

// sortRequestsByDeadline 按 deadline 给出的截止时刻排序（同截止时刻按使用
// 账户、请求编号排序），供各类批量到期处理共用，保证账本追加顺序确定。
func sortRequestsByDeadline(reqs []*request, deadline func(req *request) time.Time) {
	sort.SliceStable(reqs, func(i, j int) bool {
		if di, dj := deadline(reqs[i]), deadline(reqs[j]); !di.Equal(dj) {
			return di.Before(dj)
		}
		if reqs[i].accountID != reqs[j].accountID {
			return reqs[i].accountID < reqs[j].accountID
		}
		return reqs[i].requestID < reqs[j].requestID
	})
}

// refreshReservedLocked 在持锁状态下检查单笔已预留请求是否已到最长预留
// 时长；截止时刻及之后转为“预留超时”终态并退回全额预留。必须在持锁状态
// 下调用。
func (w *Wallet) refreshReservedLocked(req *request, now time.Time) {
	if req.state != RequestReserved || req.reserveDuration <= 0 {
		return
	}
	if now.Before(req.reserveDeadline) {
		return
	}
	w.expireReservationLocked(req, req.reserveDeadline)
}

// expirePendingApprovalsLocked 惰性结清当前全部已到等待期限（含到期时刻）
// 的待审批请求，使它们进入过期终态并留下状态记录。必须在持锁状态下调用。
func (w *Wallet) expirePendingApprovalsLocked(now time.Time) {
	pending := make([]*request, 0)
	for _, req := range w.requests {
		if req.state == RequestPendingApproval {
			pending = append(pending, req)
		}
	}
	w.settlePendingLocked(pending, now, nil)
}

// expireReservationsLocked 惰性结清当前全部已到期（含到期时刻）的预留。
// 所有账户/余额/策略/请求/账本查询以及新申请、批准的资金检查入口都先调用
// 它，因此调用者无须逐笔取消即可看到已到期预留的释放结果。释放时间一律
// 记录为各请求自己的截止时刻，而不是处理时刻；账本按截止时刻顺序追加。
// 必须在持锁状态下调用。
func (w *Wallet) expireReservationsLocked(now time.Time) {
	due := make([]*request, 0)
	for _, req := range w.requests {
		if req.state == RequestReserved && req.reserveDuration > 0 && !now.Before(req.reserveDeadline) {
			due = append(due, req)
		}
	}
	sortRequestsByDeadline(due, func(req *request) time.Time { return req.reserveDeadline })
	for _, req := range due {
		w.expireReservationLocked(req, req.reserveDeadline)
	}
}

// expireReservationLocked 将一笔已预留请求转为 RequestReservationExpired
// 终态：全额退回预估费用到出资账户可用余额，减少出资账户预留余额与该
// 策略的预留总额，不增加实际费用或已花费总额。账本增加一条出资账户的
// 全额退款记录和一条使用账户的零金额超时状态记录，均关联请求编号。
// 必须在持锁状态下调用。
func (w *Wallet) expireReservationLocked(req *request, deadline time.Time) {
	payer := w.accounts[req.payerAccountID]
	// 超时不产生实际费用：预估费用全额退回出资账户可用余额，不计入策略
	// 已花费总额；释放时刻与预留截止时刻均为 deadline，与取消区分。
	w.releaseReservationLocked(w.policies[req.policyID], payer, req, req.estimatedFee, 0)
	req.state = RequestReservationExpired
	req.reserveExpiredAt = deadline

	w.ledger = append(w.ledger,
		LedgerEntry{
			Kind:      LedgerRefund,
			AccountID: payer.id,
			RequestID: req.requestID,
			Amount:    req.estimatedFee,
			Reason:    "refund reserved fee on reservation timeout",
			At:        deadline,
		},
		LedgerEntry{
			Kind:      LedgerReservationExpiration,
			AccountID: req.accountID,
			RequestID: req.requestID,
			Reason:    "reservation timed out before settlement",
			At:        deadline,
		},
	)
}

// reserveFeeLocked 一次性完成一笔费用的实际预留，供“普通申请直接受理”与
// “待审批申请被出资账户批准”两条入口共用，避免资金、请求状态与账本分别
// 维护：
//   - 全部预估费用从出资账户可用余额转入预留余额，并计入策略的预留总额；
//     策略已花费总额不变，费用始终由策略指定的出资账户承担；
//   - 请求转为已预留，并以 reservedAt 作为实际预留时刻写入预留计时
//     （启用最长预留时长时截止时刻为 reservedAt+时长，等待审批的时间不计
//     入；未启用时截止时刻保持零值）；
//   - 追加一条出资账户的预留记录，金额为预估费用全额，原因由调用方给出
//     （直接受理与批准的说明不同）。
//
// 资金变化、请求转为已预留与预留记录在同一次持锁调用中完成，不会观察到
// 只完成一部分的结果。审批路径的审批决定信息（决定时间、出资账户）与
// 使用账户零金额批准记录由 Approve 在调用本函数后另行追加，直接受理则
// 两者都不产生。必须在持锁状态下调用，且调用前已完成余额与额度检查。
func (w *Wallet) reserveFeeLocked(p *policy, payer *account, req *request, reservedAt time.Time, reason string) {
	fee := req.estimatedFee
	payer.available -= fee
	payer.reserved += fee
	p.reservedTotal += fee

	req.state = RequestReserved
	req.reservedAt = reservedAt
	req.reserveDuration = p.maxReserveDuration
	if p.maxReserveDuration > 0 {
		req.reserveDeadline = reservedAt.Add(p.maxReserveDuration)
	}

	w.ledger = append(w.ledger, LedgerEntry{
		Kind:      LedgerReserve,
		AccountID: payer.id,
		RequestID: req.requestID,
		Amount:    fee,
		Reason:    reason,
		At:        reservedAt,
	})
}

// releaseReservationLocked 一次性释放一笔已预留费用，供“结算实际费用”、
// “取消已预留请求”与“预留超时全额退回”三个入口共用，使三种操作的资金
// 核算遵循同一规则，避免分别维护出资账户余额与策略预留总额：
//   - 无论结算、取消还是超时，出资账户的预留余额与该策略的预留总额都按
//     本请求的预估费用全额减少；其他请求占用的金额保持不变；
//   - refund 退回该出资账户的可用余额（资金始终归策略指定的出资账户，不
//     因申请账户不同而改变），spent 计入策略已花费总额：
//     结算时 refund=预估-实际、spent=实际（实际为零时全额退回，实际等于
//     预估时 refund 为零）；取消与预留超时 refund=预估全额、spent=0；
//   - 本函数只统一资金核算，不改变请求状态、终态时间或账本：状态、终态
//     （已结算/已取消/独立的预留超时）与各自的账本记录（实际扣减、正数
//     差额才追加的退款、超时状态记录）仍由各调用方按原内容与顺序追加。
//
// 账户余额、策略金额与调用方随后写入的请求状态、账本在同一把锁内连续
// 完成，不会观察到只释放一部分的结果。p 为该请求所属策略；与超时路径
// 原有的防御一致，策略缺失时只释放账户余额、不触碰策略总额。必须在持锁
// 状态下调用。
func (w *Wallet) releaseReservationLocked(p *policy, payer *account, req *request, refund, spent int64) {
	fee := req.estimatedFee
	payer.reserved -= fee
	payer.available += refund
	if p != nil {
		p.reservedTotal -= fee
		p.spentTotal += spent
	}
}

// quotaWouldExceedLocked 判断在策略 p 上再计入 fee 后，共享累计合计是否
// 严格超过累计上限，并返回计入前“现存预留 + 已结算实际费用”的合计（用于
// 错误信息；该合计本身越过 int64 范围时返回 0）。现存预留、已结算实际费用
// 与本次费用各自合法、但合计越过 int64 范围时 exceed 同样为 true：不能让
// 求和回绕成小（或负）数后被当成额度充足。累计上限与单次上限仍允许取
// int64 最大值，这里不缩小金额范围。必须在持锁状态下调用。
func quotaWouldExceedLocked(p *policy, fee int64) (used int64, exceed bool) {
	used, ok := addInt64(p.reservedTotal, p.spentTotal)
	if !ok {
		return 0, true
	}
	total, ok := addInt64(used, fee)
	if !ok {
		return used, true
	}
	return used, total > p.maxTotal
}

// Request 查询某使用账户下的代付请求。待审批请求到期即转为过期终态，
// 已预留请求到最长预留时长即转为预留超时终态，查询结果反映最新状态；
// 超时释放时间记录的是截止时刻本身，而不是本次查询时刻。
func (w *Wallet) Request(accountID, requestID string) (RequestView, error) {
	w.mu.Lock()
	defer w.mu.Unlock()

	req, _, err := w.lookupRequest(accountID, requestID)
	if err != nil {
		return RequestView{}, err
	}
	now := w.now()
	w.refreshPendingLocked(req, now)
	w.refreshReservedLocked(req, now)
	return req.view(), nil
}

// Ledger 返回全部账本记录的副本，按产生顺序排列。
// 申请被拒绝的记录（Kind 为 LedgerRejection）也包含在内并带有原因。
// 查询时已到期预留的自动退款与超时留痕也会在返回前补齐。
func (w *Wallet) Ledger() []LedgerEntry {
	w.mu.Lock()
	defer w.mu.Unlock()

	w.expireReservationsLocked(w.now())
	out := make([]LedgerEntry, len(w.ledger))
	copy(out, w.ledger)
	return out
}

// AccountLedger 返回与指定账户相关的账本记录副本。
//
// 对出资账户返回预留、扣减、退回等资金变动记录；对待审批、批准、拒绝、
// 取消、过期等状态记录（无金额变动），其 AccountID 为发起申请的使用
// 账户，因此按使用账户查询可看到该请求的完整状态留痕。
func (w *Wallet) AccountLedger(accountID string) []LedgerEntry {
	w.mu.Lock()
	defer w.mu.Unlock()

	w.expireReservationsLocked(w.now())
	var out []LedgerEntry
	for _, e := range w.ledger {
		if e.AccountID == accountID {
			out = append(out, e)
		}
	}
	return out
}

// lookupRequest 必须在持锁状态下调用。
func (w *Wallet) lookupRequest(accountID, requestID string) (*request, *policy, error) {
	req, ok := w.requests[requestKey{accountID: accountID, requestID: requestID}]
	if !ok {
		return nil, nil, fmt.Errorf("%w: account %s request %s", ErrRequestNotFound, accountID, requestID)
	}
	return req, w.policies[req.policyID], nil
}

// reject 记录无需持锁快速校验阶段的拒绝（当前没有此类调用，保留对称接口）。
func (w *Wallet) reject(in RequestInput, cause error) error {
	w.mu.Lock()
	defer w.mu.Unlock()
	w.appendRejection(in, w.now(), cause)
	return cause
}

// rejectLocked 在持锁状态下记录拒绝原因并原样返回错误。
func (w *Wallet) rejectLocked(in RequestInput, at time.Time, cause error) error {
	w.appendRejection(in, at, cause)
	return cause
}

// appendRejection 必须在持锁状态下调用。拒绝记录不涉及金额变动，
// 只记录使用账户、请求编号与具体原因。
func (w *Wallet) appendRejection(in RequestInput, at time.Time, cause error) {
	w.ledger = append(w.ledger, LedgerEntry{
		Kind:      LedgerRejection,
		AccountID: in.AccountID,
		RequestID: in.RequestID,
		Reason:    cause.Error(),
		At:        at,
	})
}

func (a *account) view() AccountView {
	return AccountView{
		ID: a.id,
		Balances: Balances{
			Available: a.available,
			Reserved:  a.reserved,
		},
		CreatedAt: a.createdAt,
	}
}

func (s *session) view() SessionView {
	state := SessionActive
	if s.revoked {
		state = SessionRevoked
	}
	return SessionView{
		ID:        s.id,
		AccountID: s.accountID,
		DeviceID:  s.deviceID,
		ExpiresAt: s.expiresAt,
		State:     state,
		CreatedAt: s.createdAt,
	}
}

func (p *policy) view() PolicyView {
	ids := make([]string, 0, len(p.allowedAccounts))
	for id := range p.allowedAccounts {
		ids = append(ids, id)
	}
	return PolicyView{
		PolicySpec: PolicySpec{
			ID:                 p.id,
			PayerAccountID:     p.payerAccountID,
			AllowedAccountIDs:  ids,
			Operation:          p.operation,
			Payee:              p.payee,
			StartsAt:           p.startsAt,
			EndsAt:             p.endsAt,
			MaxPerRequest:      p.maxPerRequest,
			MaxTotal:           p.maxTotal,
			ApprovalThreshold:  p.approvalThreshold,
			ApprovalWait:       p.approvalWait,
			MaxReserveDuration: p.maxReserveDuration,
		},
		ReservedTotal:        p.reservedTotal,
		SpentTotal:           p.spentTotal,
		Deactivated:          p.deactivated,
		DeactivatedAt:        p.deactivatedAt,
		DeactivatorAccountID: p.deactivatorAccountID,
		DeactivateReason:     p.deactivateReason,
	}
}

func (r *request) view() RequestView {
	return RequestView{
		PolicyID:          r.policyID,
		RequestID:         r.requestID,
		AccountID:         r.accountID,
		PayerAccountID:    r.payerAccountID,
		Operation:         r.operation,
		Payee:             r.payee,
		EstimatedFee:      r.estimatedFee,
		ActualFee:         r.actualFee,
		State:             r.state,
		CreatedAt:         r.createdAt,
		SettledAt:         r.settledAt,
		WaitDeadline:      r.waitDeadline,
		ReservedAt:        r.reservedAt,
		ReserveDuration:   r.reserveDuration,
		ReserveDeadline:   r.reserveDeadline,
		ReserveExpiredAt:  r.reserveExpiredAt,
		DecidedAt:         r.decidedAt,
		ApproverAccountID: r.approverAccountID,
		RejectReason:      r.rejectReason,
	}
}

