			t.Fatal(err)
		}
		w2, err := restoreAt(data, t0.Add(3*time.Minute))
		if err != nil {
			t.Fatalf("restore: %v", err)
		}
		r, err := w2.Request("u1", "r2")
		if err != nil {
			t.Fatal(err)
		}
		if r.State != RequestReserved {
			t.Fatalf("state = %v, want reserved", r.State)
		}
	})
}

